{"toolCallId":"call_f727ff95e1d2486c90db4c9f","toolName":"editor","input":{"path":"C:\kamlesh\test\games\zombie3\js\utils.js","new_text":"/* =====================================================================
   DEAD ZONE 3D  —  js/utils.js
   Shared math helpers, seeded RNG, spatial collision grid, particle
   system, decal manager and camera shake.  Plain script (no modules);
   everything hangs off the global `Z3` namespace.
   ===================================================================== */
window.Z3 = window.Z3 || {};
(function (Z3) {
  'use strict';

  /* ---------------------------------------------------------------- math */
  const TAU = Math.PI * 2;
  const clamp = (v, a, b) => (v < a ? a : (v > b ? b : v));
  const lerp = (a, b, t) => a + (b - a) * t;
  const rand = (a, b) => (b === undefined ? Math.random() * a : a + Math.random() * (b - a));
  const randInt = (a, b) => Math.floor(rand(a, b + 1));
  const pick = (arr) => arr[(Math.random() * arr.length) | 0];
  const chance = (p) => Math.random() < p;
  const smoothstep = (t) => t * t * (3 - 2 * t);
  /** frame-rate independent exponential smoothing */
  const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
  /** shortest signed angular difference */
  const angleDelta = (a, b) => {
    let d = (b - a) % TAU;
    if (d > Math.PI) d -= TAU;
    if (d < -Math.PI) d += TAU;
    return d;
  };
  const dampAngle = (a, b, lambda, dt) => a + angleDelta(a, b) * (1 - Math.exp(-lambda * dt));
  const dist2D = (ax, az, bx, bz) => Math.hypot(bx - ax, bz - az);

  Z3.TAU = TAU;
  Z3.clamp = clamp;
  Z3.lerp = lerp;
  Z3.rand = rand;
  Z3.randInt = randInt;
  Z3.pick = pick;
  Z3.chance = chance;
  Z3.smoothstep = smoothstep;
  Z3.damp = damp;
  Z3.dampAngle = dampAngle;
  Z3.angleDelta = angleDelta;
  Z3.dist2D = dist2D;

  /* ------------------------------------------------------------ rng ---- */
  /** mulberry32 – tiny deterministic PRNG so levels look the same each run */
  function Rng(seed) {
    let s = (seed >>> 0) || 1;
    const next = () => {
      s = (s + 0x6d2b79f5) >>> 0;
      let t = s;
      t = Math.imul(t ^ (t >>> 15), 1 | t);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
    return {
      next,
      range: (a, b) => a + next() * (b - a),
      int: (a, b) => Math.floor(a + next() * (b - a + 1)),
      pick: (arr) => arr[Math.floor(next() * arr.length) % arr.length],
      chance: (p) => next() < p,
      sign: () => (next() < 0.5 ? -1 : 1)
    };
  }
  Z3.Rng = Rng;

  /* ------------------------------------------------- spatial grid ------ */
  /**
   * Uniform grid over the XZ plane holding axis-aligned boxes.
   * Used for player/zombie collision, zombie obstacle avoidance and
   * cheap line-of-sight tests.
   */
  function Grid(cellSize) {
    this.cell = cellSize || 8;
    this.map = new Map();
    this.boxes = [];
    this.stamp = 0;
  }
  Grid.prototype._cells = function (minX, minZ, maxX, maxZ, cb) {
    const c = this.cell;
    const x0 = Math.floor(minX / c), x1 = Math.floor(maxX / c);
    const z0 = Math.floor(minZ / c), z1 = Math.floor(maxZ / c);
    for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) cb(x + ',' + z);
  };
  /**
   * box = { minX, maxX, minZ, maxZ, minY, maxY, tag, solid, mesh }
   * `solid` boxes block movement; `tag` is used for surfaces / decals.
   */
  Grid.prototype.add = function (box) {
    box.minY = box.minY === undefined ? 0 : box.minY;
    box.maxY = box.maxY === undefined ? 100 : box.maxY;
    box.solid = box.solid !== false;
    box._seen = -1;
    this.boxes.push(box);
    const self = this;
    this._cells(box.minX, box.minZ, box.maxX, box.maxZ, function (k) {
      let arr = self.map.get(k);
      if (!arr) { arr = []; self.map.set(k, arr); }
