window.Z3 = window.Z3 || {};
(function (Z3) {
  'use strict';
  const clamp = Z3.clamp;
  const TAU = Z3.TAU;

  const FALLBACK_COLORS = {
    asphalt: '#3a3a3c', roadLine: '#3a3a3c', sidewalk: '#8d8b85', concrete: '#8f8d88',
    plaster: '#9a978f', brick: '#7b5a4a', wood: '#7a5c3a', metal: '#6f7377',
    rustMetal: '#7d5233', dirt: '#6b5b47', grassDry: '#6f6a45', bark: '#4d3f31',
    roof: '#4a4a4d', windowGrid: '#242830', bloodSplat: '#3a0508', bloodPool: '#2f0406',
    crate: '#7c5f3c', fleshSkin: '#8b8b6e', cloth: '#4a4a44', bulletHole: '#101010',
    poster: '#8a8577', sign: '#3f5340', tileFloor: '#7c7a74', carPaint: '#5a6268'
  };
  const flatCache = new Map();

  /** Tiny flat-colour texture used when a texture factory is unavailable. */
  function flatTexture(name) {
    const key = name || 'generic';
    if (flatCache.has(key)) return flatCache.get(key);
    const c = document.createElement('canvas');
    c.width = c.height = 32;
    const ctx = c.getContext('2d');
    ctx.fillStyle = FALLBACK_COLORS[key] || '#6a6a6a';
    ctx.fillRect(0, 0, 32, 32);
    ctx.fillStyle = 'rgba(0,0,0,0.18)';
    for (let i = 0; i < 160; i++) ctx.fillRect((Math.random() * 32) | 0, (Math.random() * 32) | 0, 2, 2);
    const t = new THREE.CanvasTexture(c);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.encoding = THREE.sRGBEncoding;
    flatCache.set(key, t);
    return t;
  }

  const texCache = new Map();
  /**
   * Safely call a Z3Tex factory (textures.js) and cache the result.
   * Falls back to a flat colour so the game always renders.
   */
  function getTex(name, arg) {
    const key = name + ':' + (arg === undefined ? '' : String(arg));
    if (texCache.has(key)) return texCache.get(key);
    let out = null;
    const T = window.Z3Tex;
    try {
      if (T && typeof T[name] === 'function') out = T[name](arg);
    } catch (e) {
      console.warn('[Z3] texture factory "' + name + '" failed', e);
    }
    if (!out || !out.map) {
      out = { map: flatTexture(name), normalMap: null, roughness: 0.92, metalness: 0, fallback: true };
    }
    texCache.set(key, out);
    return out;
  }

  function cloneTex(t, rx, ry) {
    if (!t) return null;
    const c = t.clone();
    c.needsUpdate = true;
    c.wrapS = c.wrapT = THREE.RepeatWrapping;
    c.repeat.set(rx, ry);
    return c;
  }

  const matCache = new Map();
  /**
