   * `rx / ry` tile the texture; they are rounded so the number of unique
   * texture variants - and therefore GPU memory - stays small.
   */
  function material(texName, arg, rx, ry, opts) {
    rx = Math.max(0.5, Math.round((rx || 1) * 2) / 2);
    ry = Math.max(0.5, Math.round((ry || 1) * 2) / 2);
    opts = opts || {};
    const optKey = JSON.stringify(opts);
    const key = texName + '|' + (arg === undefined ? '' : arg) + '|' + rx + '|' + ry + '|' + optKey;
    if (matCache.has(key)) return matCache.get(key);
    const t = getTex(texName, arg);
    const m = new THREE.MeshStandardMaterial({
      map: cloneTex(t.map, rx, ry),
      normalMap: cloneTex(t.normalMap, rx, ry),
      roughness: opts.roughness === undefined ? t.roughness : opts.roughness,
      metalness: opts.metalness === undefined ? t.metalness : opts.metalness
    });
    if (opts.color !== undefined) m.color.setHex(opts.color);
    if (opts.side !== undefined) m.side = opts.side;
    if (opts.transparent) m.transparent = true;
    if (opts.alphaTest !== undefined) m.alphaTest = opts.alphaTest;
    if (opts.opacity !== undefined) m.opacity = opts.opacity;
    if (opts.emissive !== undefined) m.emissive.setHex(opts.emissive);
    if (opts.emissiveIntensity !== undefined) m.emissiveIntensity = opts.emissiveIntensity;
    if (opts.envMapIntensity !== undefined) m.envMapIntensity = opts.envMapIntensity;
