    g.addColorStop(0.0, '#05070d');
    g.addColorStop(0.42, '#0c1220');
    g.addColorStop(0.62, '#1b2230');
    g.addColorStop(0.80, '#2b303a');
    g.addColorStop(1.0, '#3b3a35');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 64, 256);
    // faint clouds
    ctx.globalAlpha = 0.10;
    ctx.fillStyle = '#8d97ab';
    for (let i = 0; i < 26; i++) {
      const y = 20 + Math.random() * 150;
      ctx.beginPath();
      ctx.ellipse(Math.random() * 64, y, 20 + Math.random() * 26, 5 + Math.random() * 9, 0, 0, TAU);
      ctx.fill();
    }
