    parent.add(m);
    return m;
  }
  /** Ground-plane quad (roads, decals-on-ground, paper). */
  function quad(w, d, mat) {
    const m = new THREE.Mesh(GEO.plane, mat);
    m.rotation.x = -Math.PI / 2;
    m.scale.set(w, d, 1);
    m.receiveShadow = true;
