  /** Axis-aligned collider for a box-ish prop at (x,z) with size w/d/h. */
  function collider(grid, x, z, w, d, h, tag, solid, blockSight) {
    return grid.add({
      minX: x - w / 2, maxX: x + w / 2, minZ: z - d / 2, maxZ: z + d / 2,
