  /**
   * A city building. Returns the group. `cfg.enterable` cuts a doorway in
   * `cfg.doorFace` and leaves the interior open (with loot lights).
   */
  function addBuilding(world, cfg, rng) {
    const parent = world.cityGroup;
    const grid = world.grid;
    const T = 0.42;
    const w = cfg.w, d = cfg.d, h = cfg.h, bx = cfg.x, bz = cfg.z;
    const wallName = cfg.wall || 'brick';
    const wallMat = material(wallName, null, Math.max(1, w / 4), Math.max(1, h / 3), { roughness: 0.92 });

    // side walls (full depth, inset by wall thickness to avoid z-fighting)
    placeBox(parent, T, h, d, bx - w / 2, 0, bz, wallMat);
    placeBox(parent, T, h, d, bx + w / 2, 0, bz, wallMat);
    collider(grid, bx - w / 2, bz, T, d, h, 'wall');
    collider(grid, bx + w / 2, bz, T, d, h, 'wall');

    const doorFace = cfg.doorFace || '-z';
    const northSouth = [
      { face: '-z', z: bz - d / 2, len: w },
      { face: '+z', z: bz + d / 2, len: w }
    ];
    for (let i = 0; i < 2; i++) {
      const ns = northSouth[i];
      const isDoorWall = cfg.enterable && doorFace === ns.face;
      if (!isDoorWall) {
        placeBox(parent, w, h, T, bx, 0, ns.z, wallMat);
        collider(grid, bx, ns.z, w, T, h, 'wall');
