      if (lw > 0.2) {
        placeBox(parent, lw, h, T, bx - w / 2 + lw / 2, 0, ns.z, wallMat);
        collider(grid, bx - w / 2 + lw / 2, ns.z, lw, T, h, 'wall');
      }
      const rw = (bx + w / 2) - rightStart;
      if (rw > 0.2) {
        placeBox(parent, rw, h, T, rightStart + rw / 2, 0, ns.z, wallMat);
        collider(grid, rightStart + rw / 2, ns.z, rw, T, h, 'wall');
      }
      placeBox(parent, doorW, h - doorH, T, gapX, doorH, ns.z, wallMat);
      // broken door leaning in the frame
      const door = placeBox(parent, doorW * 0.92, doorH * 0.9, 0.12, gapX + 0.5, 0, ns.z + 0.4,
