      door.rotation.z = 0.06;
    }

    // interior floor + ceiling slab
    if (cfg.enterable) {
      const fl = quad(w - T * 2, d - T * 2, material('tileFloor', null, (w - T * 2) / 3, (d - T * 2) / 3, { roughness: 0.85 }));
