  /**
   * A city building. `cfg.enterable` cuts a doorway in `cfg.doorFace` and
   * leaves the ground floor hollow so the player can fight indoors.
   */
  function addBuilding(world, cfg, rng) {
    const parent = world.cityGroup;
    const grid = world.grid;
    const T = 0.42;
    const w = cfg.w, d = cfg.d, h = cfg.h, bx = cfg.x, bz = cfg.z;
    const wallMat = material(cfg.wall || 'brick', null, Math.max(1, w / 4), Math.max(1, h / 3), { roughness: 0.92 });

    // east / west walls
    placeBox(parent, T, h, d, bx - w / 2, 0, bz, wallMat);
    placeBox(parent, T, h, d, bx + w / 2, 0, bz, wallMat);
    collider(grid, bx - w / 2, bz, T, d, h, 'wall');
    collider(grid, bx + w / 2, bz, T, d, h, 'wall');

    const doorFace = cfg.doorFace || '-z';
    const nsList = [{ face: '-z', z: bz - d / 2 }, { face: '+z', z: bz + d / 2 }];
    for (let i = 0; i < 2; i++) {
      const ns = nsList[i];
      if (!(cfg.enterable && doorFace === ns.face)) {
        placeBox(parent, w, h, T, bx, 0, ns.z, wallMat);
        collider(grid, bx, ns.z, w, T, h, 'wall');
        continue;
      }
      // doorway: two wall segments plus a lintel above the opening
      const doorW = 1.7, doorH = 2.5;
      const gapX = bx + rng.range(-w / 4, w / 4);
      const leftLen = (gapX - doorW / 2) - (bx - w / 2);
      const rightStart = gapX + doorW / 2;
      const rightLen = (bx + w / 2) - rightStart;
      if (leftLen > 0.2) {
        placeBox(parent, leftLen, h, T, bx - w / 2 + leftLen / 2, 0, ns.z, wallMat);
        collider(grid, bx - w / 2 + leftLen / 2, ns.z, leftLen, T, h, 'wall');
      }
      if (rightLen > 0.2) {
        placeBox(parent, rightLen, h, T, rightStart + rightLen / 2, 0, ns.z, wallMat);
        collider(grid, rightStart + rightLen / 2, ns.z, rightLen, T, h, 'wall');
      }
      placeBox(parent, doorW, h - doorH, T, gapX, doorH, ns.z, wallMat);
      const door = placeBox(parent, doorW * 0.92, doorH * 0.92, 0.12, gapX + 0.45, 0, ns.z + 0.35,
        material('wood', null, 1, 1, { roughness: 0.95 }), rng.range(0.35, 1.0));
      door.rotation.z = 0.05;
      void doorW;
    }

    if (cfg.enterable) {
      const fl = quad(w - T * 2, d - T * 2,
        material('tileFloor', null, (w - T * 2) / 3, (d - T * 2) / 3, { roughness: 0.85 }));
      fl.position.set(bx, 0.02, bz);
      parent.add(fl);
      placeBox(parent, w + 0.4, 0.42, d + 0.4, bx, h, bz, material('concrete', null, 3, 3, { roughness: 0.95 }));
    } else {
      placeBox(parent, w, h, d, bx, 0, bz,
        material('concrete', null, Math.max(1, w / 4), Math.max(1, h / 3), { roughness: 0.94 }));
    }

    const faces = cfg.faces || ['-z'];
    for (let i = 0; i < faces.length; i++) addWindows(parent, faces[i], bx, bz, w, d, h, rng);
    addRoofDetails(parent, grid, bx, bz, w, d, h, rng);
    return parent;
  }
  Z3.addBuilding = addBuilding;
