  /* --------------------------------------------------------- props ----- */
  /** Collider for a rectangle rotated around Y (AABB of the rotated box). */
  function colliderRot(grid, x, z, w, d, rot, h, tag, solid, blockSight) {
    const c = Math.abs(Math.cos(rot)), s = Math.abs(Math.sin(rot));
    const hw = (w / 2) * c + (d / 2) * s;
    const hd = (w / 2) * s + (d / 2) * c;
    return grid.add({
      minX: x - hw, maxX: x + hw, minZ: z - hd, maxZ: z + hd,
      minY: 0, maxY: h, tag: tag, solid: solid !== false, blockSight: blockSight
    });
  }

  /** Abandoned car – rusty, dusty, sometimes burnt out or flipped. */
  function addCar(world, x, z, rot, rng) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    world.cityGroup.add(g);
    const burnt = rng.chance(0.28);
    const color = rng.pick([0x39424b, 0x53413a, 0x2c3b34, 0x5f5f5a, 0x453a4d, 0x7a7568, 0x1f2429]);
    const paint = material('carPaint', color, 2, 2, {
      roughness: burnt ? 0.97 : 0.34, metalness: burnt ? 0.2 : 0.62,
      color: burnt ? 0x35302c : 0xffffff
    });
    const glass = material('windowGrid', null, 2, 1, { color: 0x14181d, roughness: 0.16, metalness: 0.5 });
    const rubber = material('rustMetal', null, 1, 1, { color: 0x15161a, roughness: 0.9, metalness: 0.1 });
    placeBox(g, 1.92, 0.58, 4.3, 0, 0.34, 0, paint);
    placeBox(g, 1.72, 0.6, 2.05, 0, 0.92, -0.1, paint);
    placeBox(g, 1.74, 0.5, 1.9, 0.02, 0.98, -0.1, glass);
    placeBox(g, 1.98, 0.16, 0.3, 0, 0.62, 2.08, rubber);   // bumpers
    placeBox(g, 1.98, 0.16, 0.3, 0, 0.62, -2.08, rubber);
    const wheelMat = rubber;
    const wheels = [[-1.0, 1.45], [1.0, 1.45], [-1.0, -1.45], [1.0, -1.45]];
    for (let i = 0; i < 4; i++) {
      if (burnt && i === 2) continue;                       // missing wheel
      const flat = rng.chance(burnt ? 0.5 : 0.12);
      const wm = new THREE.Mesh(GEO.cyl, wheelMat);
      wm.scale.set(flat ? 0.5 : 0.66, 0.3, flat ? 0.5 : 0.66);
      wm.rotation.z = Math.PI / 2;
      wm.position.set(wheels[i][0], flat ? 0.22 : 0.34, wheels[i][1]);
      wm.castShadow = true;
      g.add(wm);
    }
    // open doors / broken hood for silhouettes
    if (rng.chance(0.4)) {
      placeBox(g, 0.1, 1.0, 1.2, 0.98, 0.4, -0.4, paint).rotation.y = rng.range(0.4, 1.1);
    }
    if (rng.chance(0.32)) {
      const hood = placeBox(g, 1.6, 0.12, 1.4, 0, 0.62, 1.6, paint);
      hood.rotation.x = rng.range(-0.7, -0.3);
    }
    colliderRot(world.grid, x, z, 2.05, 4.45, rot, 1.25, 'car');
    world.surfaces.push({ minX: x - 2.6, maxX: x + 2.6, minZ: z - 2.6, maxZ: z + 2.6, type: 'metal' });
    return g;
  }

  /** Rusted skip / dumpster with a lid askew. */
  function addDumpster(world, x, z, rot, rng) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    world.cityGroup.add(g);
    const m = material('rustMetal', null, 2, 1, { roughness: 0.86, metalness: 0.45 });
    placeBox(g, 2.2, 1.05, 1.35, 0, 0.1, 0, m);
    const lid = placeBox(g, 2.1, 0.09, 1.2, 0.15, 1.18, -0.1, m);
    lid.rotation.z = rng.range(-0.35, -0.12);
    colliderRot(world.grid, x, z, 2.3, 1.45, rot, 1.35, 'dumpster');
    return g;
  }

  /** 200 L oil drum – some upright, some toppled, occasionally burning. */
  function addBarrel(world, x, z, rng, burning) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    world.cityGroup.add(g);
    const m = material('rustMetal', null, 2, 2, { roughness: 0.8, metalness: 0.5 });
    const upright = !burning && !rng.chance(0.35);
    const b = new THREE.Mesh(GEO.cyl, m);
    b.scale.set(0.62, 0.88, 0.62);
    b.castShadow = true;
    if (upright) {
      b.position.y = 0.44;
      g.add(b);
      colliderRot(world.grid, x, z, 0.64, 0.64, 0, 0.9, 'barrel');
    } else {
      b.rotation.z = Math.PI / 2;
      b.position.set(0, 0.31, rng.range(-0.1, 0.1));
      g.add(b);
      colliderRot(world.grid, x, z, 1.0, 0.64, 0, 0.66, 'barrel');
    }
    if (burning) {
      const fire = new THREE.Mesh(GEO.cyl, new THREE.MeshBasicMaterial({ color: 0xff7a1e }));
      fire.scale.set(0.4, 0.5, 0.4);
      fire.position.y = 0.9;
      g.add(fire);
      const light = new THREE.PointLight(0xff8a2a, 1.5, 12, 2);
      light.position.set(x, 1.1, z);
      world.addLight(light, 1.5);
      world.firePoints.push({ x: x, y: 1.0, z: z, mesh: fire });
      world.loops.push(function () { fire.scale.set(0.35 + Math.random() * 0.12, 0.42 + Math.random() * 0.2, 0.35 + Math.random() * 0.12); });
    }
    return g;
  }

  /** Wooden crate / pallet stack. */
  function addCrate(world, x, z, rot, rng) {
    const s = rng.range(0.85, 1.15);
    const m = material('crate', null, Math.max(1, s), Math.max(1, s), { roughness: 0.95 });
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    world.cityGroup.add(g);
    const stack = rng.int(1, 3);
    for (let i = 0; i < stack; i++) {
      const cs = s * (1 - i * 0.08);
      placeBox(g, cs, cs, cs, rng.range(-0.25, 0.25), i * cs, rng.range(-0.25, 0.25), m, rng.range(-0.4, 0.4));
    }
    colliderRot(world.grid, x, z, s * 1.3, s * 1.3, rot, s * stack, 'crate');
    world.surfaces.push({ minX: x - 1.4, maxX: x + 1.4, minZ: z - 1.4, maxZ: z + 1.4, type: 'wood' });
    return g;
  }
  Z3.addCar = addCar;
  Z3.addDumpster = addDumpster;
  Z3.addBarrel = addBarrel;
  Z3.addCrate = addCrate;
  Z3.colliderRot = colliderRot;
})(window.Z3);","old_text":"  Z3.addBuilding = addBuilding;
