  /** Sandbag wall – low cover that zombies can see and shoot over. */
  function addSandbags(world, x, z, len, rot, rng) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    world.cityGroup.add(g);
    const m = material('cloth', 0x6b5f45, 1, 1, { roughness: 0.98, color: 0xa39c84 });
    const cols = Math.max(2, Math.round(len / 0.72));
    for (let c = 0; c < cols; c++) {
      for (let row = 0; row < 2; row++) {
        const ox = c * 0.72 - len / 2 + 0.36;
        const oz = (row === 0 ? 0 : 0.16) + rng.range(-0.05, 0.05);
        const b = boxMesh(m);
        b.scale.set(0.74, 0.28, 0.46);
        b.rotation.y = rng.range(-0.2, 0.2);
        b.position.set(ox, 0.15 + row * 0.27, oz);
        g.add(b);
      }
    }
    colliderRot(world.grid, x, z, len, 0.85, rot, 0.62, 'sandbag');
    world.surfaces.push({ minX: x - len, maxX: x + len, minZ: z - 1.2, maxZ: z + 1.2, type: 'dirt' });
    return g;
  }

  /** Concrete jersey barrier used to close off streets. */
  function addBarrier(world, x, z, len, rot) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    world.cityGroup.add(g);
    const m = material('concrete', null, len / 2, 1, { roughness: 0.95 });
    placeBox(g, len, 0.42, 0.62, 0, 0, 0, m);
    placeBox(g, len, 0.62, 0.4, 0, 0.42, 0, m);
    colliderRot(world.grid, x, z, len, 0.66, rot, 1.04, 'barrier');
    return g;
  }

  /** Chain-link fence: blocks movement but not sight. */
  function addFence(world, x, z, len, rot, rng) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    world.cityGroup.add(g);
    const m = material('metal', null, len / 3, 1, { roughness: 0.7, metalness: 0.6, color: 0x8e979c });
    const panel = new THREE.Mesh(GEO.plane, m);
    panel.scale.set(len, 1.9, 1);
    panel.position.set(0, 1.0, 0);
    panel.material.side = THREE.DoubleSide;
    panel.material.transparent = true;
    panel.material.opacity = 0.55;
    g.add(panel);
    const posts = Math.max(2, Math.round(len / 2.5) + 1);
    for (let i = 0; i < posts; i++) {
      const px = -len / 2 + (len / (posts - 1)) * i;
      const p = placeBox(g, 0.1, 2.1, 0.1, px, 0, 0, m);
      p.rotation.z = rng.range(-0.03, 0.03);
    }
    colliderRot(world.grid, x, z, len, 0.12, rot, 2.0, 'fence', true, false);
    return g;
  }

  /** Dead tree with bare branches. */
  function addDeadTree(world, x, z, rng) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rng.range(0, TAU);
    world.cityGroup.add(g);
    const m = material('bark', null, 1, 2, { roughness: 0.99 });
    const h = rng.range(4.2, 6.5);
    const trunk = new THREE.Mesh(GEO.cylLo, m);
    trunk.scale.set(0.46, h, 0.46);
    trunk.position.y = h / 2;
    trunk.rotation.z = rng.range(-0.05, 0.05);
    trunk.castShadow = true;
    g.add(trunk);
    const branches = rng.int(3, 6);
    for (let i = 0; i < branches; i++) {
      const bl = rng.range(1.4, 3.1);
      const b = new THREE.Mesh(GEO.cylLo, m);
      b.scale.set(0.16, bl, 0.16);
      const y = rng.range(h * 0.6, h * 0.95);
      const a = rng.range(0, TAU);
      b.position.set(Math.cos(a) * bl * 0.28, y, Math.sin(a) * bl * 0.28);
      b.rotation.set(rng.range(0.5, 1.1) * (Math.random() < 0.5 ? 1 : -1), 0, a);
      b.castShadow = true;
      g.add(b);
    }
    colliderRot(world.grid, x, z, 0.6, 0.6, 0, h, 'tree', true, false);
    world.surfaces.push({ minX: x - 3, maxX: x + 3, minZ: z - 3, maxZ: z + 3, type: 'dirt' });
    return g;
  }

  /** Streetlight pole (working ones get a point light + emissive head). */
  function addStreetlight(world, x, z, rot, working) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    world.cityGroup.add(g);
    const m = material('metal', null, 1, 3, { roughness: 0.62, metalness: 0.65, color: 0x8b9299 });
    placeBox(g, 0.18, 7.2, 0.18, 0, 0, 0, m);
    const arm = placeBox(g, 2.2, 0.14, 0.14, 1.0, 7.0, 0, m);
    arm.rotation.z = -0.08;
    const head = placeBox(g, 0.7, 0.16, 0.34, 1.95, 6.85, 0, m);
    if (working) {
      const lamp = new THREE.Mesh(GEO.box, new THREE.MeshBasicMaterial({ color: 0xfff0c4 }));
      lamp.scale.set(0.56, 0.06, 0.26);
      lamp.position.set(1.95, 6.8, 0);
      g.add(lamp);
      head.material = m;
      const lx = x + Math.cos(rot) * 1.95;
      const lz = z - Math.sin(rot) * 1.95;
      const light = new THREE.PointLight(0xffd9a0, 0.0001, 22, 2);
      light.position.set(lx, 6.6, lz);
      light.castShadow = false;
      world.addLight(light, 1.35);
      world.flickerList.push({ light: light, base: 1.35, phase: Math.random() * 100, speed: Z3.rand(0.6, 2.4), broken: Math.random() < 0.34 });
    }
    colliderRot(world.grid, x, z, 0.3, 0.3, 0, 7.2, 'pole', true, false);
    return g;
  }

  /** Body of a dead survivor / zombie lying in the street. */
  function addCorpse(world, x, z, rot, rng) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = rot;
    world.cityGroup.add(g);
    const skin = material('fleshSkin', 0x8e8e74, 1, 1, { roughness: 0.85 });
    const cloth = material('cloth', 0x4a4a42, 1, 1, { roughness: 0.95, color: 0x6d6a60 });
    const torso = placeBox(g, 0.46, 0.28, 0.72, rng.range(-0.2, 0.2), 0.14, rng.range(-0.2, 0.2), cloth);
    torso.rotation.y = rng.range(0, TAU);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.12, 10, 8), skin);
    head.position.set(torso.position.x + rng.range(-0.3, 0.3), 0.13, torso.position.z + rng.range(-0.4, 0.4));
    head.castShadow = true;
    g.add(head);
    const limbs = rng.int(2, 4);
    for (let i = 0; i < limbs; i++) {
      const l = boxMesh(cloth);
      l.scale.set(0.13, 0.13, rng.range(0.5, 0.8));
      l.position.set(rng.range(-0.7, 0.7), 0.07, rng.range(-0.8, 0.8));
      l.rotation.set(0, rng.range(0, TAU), 0);
      g.add(l);
    }
    void skin;
    return g;
  }

