  /** Pile of broken concrete chunks and rebar. */
  function addRubble(world, x, z, r, rng) {
    const g = new THREE.Group();
    world.cityGroup.add(g);
    const conc = material('concrete', null, 1, 1, { roughness: 0.97 });
    const metal = material('rustMetal', null, 1, 1, { roughness: 0.75, metalness: 0.6 });
