      m.scale.set(s, s * rng.range(0.4, 0.9), s * rng.range(0.5, 1.1));
      m.position.set(x + Math.cos(a) * rr, s * 0.25, z + Math.sin(a) * rr);
      m.rotation.set(rng.range(0, 0.5), rng.range(0, TAU), rng.range(0, 0.5));
      g.add(m);
