  /* --------------------------------------------------------- layout ---- */
  const HALF = 60;          // playable half-size
  const ROAD_W = 13;        // main road width
  const SW_W = 4.5;         // sidewalk width
  const SW_Y = 0.16;        // sidewalk height

  function buildGround(world) {
    const g = new THREE.Group();
    world.cityGroup.add(g);
    const dirt = quad(400, 400, material('dirt', null, 60, 60, { roughness: 1 }));
    dirt.position.y = 0;
    g.add(dirt);

    const roadLen = HALF * 2 + 26;
    const asphaltNS = quad(ROAD_W, roadLen, material('asphalt', null, 3, 26, { roughness: 0.88 }));
    asphaltNS.position.set(0, 0.01, 0);
    g.add(asphaltNS);
    const asphaltEW = quad(roadLen, ROAD_W, material('asphalt', null, 26, 3, { roughness: 0.88 }));
    asphaltEW.position.set(0, 0.012, 0);
    g.add(asphaltEW);

    // faded lane markings
    const lane = material('roadLine', null, 1, 30, { roughness: 0.85 });
    for (let i = -1; i <= 1; i += 2) {
      const s = quad(3.6, roadLen, lane);
      s.position.set(i * 3.3, 0.02, 0);
      g.add(s);
    }
    const laneEW = material('roadLine', null, 30, 1, { roughness: 0.85 });
    for (let i = -1; i <= 1; i += 2) {
      const s = quad(roadLen, 3.6, laneEW);
      s.position.set(0, 0.022, i * 3.3);
      g.add(s);
    }

    // sidewalks (raised slabs) + curbs
    const swMat = material('sidewalk', null, 2, 22, { roughness: 0.95 });
    const swMatEW = material('sidewalk', null, 22, 2, { roughness: 0.95 });
    const curbMat = material('concrete', null, 20, 1, { roughness: 0.96, color: 0xb0aca4 });
    const off = ROAD_W / 2 + SW_W / 2;
    for (let i = -1; i <= 1; i += 2) {
      const a = quad(SW_W, roadLen, swMat);
      a.position.set(i * off, SW_Y, 0);
      g.add(a);
      const b = quad(roadLen, SW_W, swMatEW);
      b.position.set(0, SW_Y, i * off);
      g.add(b);
      world.sidewalks.push({ minX: i * off - SW_W / 2, maxX: i * off + SW_W / 2, minZ: -roadLen / 2, maxZ: roadLen / 2 });
      world.sidewalks.push({ minX: -roadLen / 2, maxX: roadLen / 2, minZ: i * off - SW_W / 2, maxZ: i * off + SW_W / 2 });
      const c1 = placeBox(g, 0.16, SW_Y, roadLen, i * (ROAD_W / 2 + 0.08), 0, 0, curbMat);
      c1.castShadow = false;
      const c2 = placeBox(g, roadLen, SW_Y, 0.16, 0, 0, i * (ROAD_W / 2 + 0.08), curbMat);
      c2.castShadow = false;
    }
    world.surfaces.push({ minX: -ROAD_W / 2, maxX: ROAD_W / 2, minZ: -HALF * 2, maxZ: HALF * 2, type: 'concrete' });
    world.surfaces.push({ minX: -HALF * 2, maxX: HALF * 2, minZ: -ROAD_W / 2, maxZ: ROAD_W / 2, type: 'concrete' });
  }

  /** Impassable ring of derelict tower blocks framing the whole arena. */
  function buildPerimeter(world, rng) {
    const m = material('concrete', null, 6, 10, { roughness: 0.96, color: 0x6c6a66 });
    const dark = material('plaster', null, 6, 10, { roughness: 0.95, color: 0x5b5a57 });
    const walls = [
      { x: 0, z: -HALF - 11, w: (HALF + 12) * 2 + 24, d: 22, faces: ['+z'] },
      { x: 0, z: HALF + 11, w: (HALF + 12) * 2 + 24, d: 22, faces: ['-z'] },
      { x: -HALF - 11, z: 0, w: 22, d: (HALF + 12) * 2 + 24, faces: ['+x'] },
      { x: HALF + 11, z: 0, w: 22, d: (HALF + 12) * 2 + 24, faces: ['-x'] }
    ];
    for (let i = 0; i < walls.length; i++) {
      const wl = walls[i];
      const h = rng.range(22, 34);
      const mat = i % 2 ? m : dark;
      placeBox(world.cityGroup, wl.w, h, wl.d, wl.x, 0, wl.z, mat);
      collider(world.grid, wl.x, wl.z, wl.w, wl.d, h, 'perimeter');
    }
  }
  Z3.WORLD_HALF = HALF;
