  function buildCity(world, rng) {
    let enterableCount = 0;
    for (let sx = -1; sx <= 1; sx += 2) {
      for (let sz = -1; sz <= 1; sz += 2) {
        for (let li = 0; li < LOT_CENTERS.length; li++) {
          for (let lj = 0; lj < LOT_CENTERS.length; lj++) {
            if (rng.chance(0.18) && !(li === 0 && lj === 0)) continue;  // open lot / plaza
            const x = sx * LOT_CENTERS[li];
            const z = sz * LOT_CENTERS[lj];
            const w = rng.range(13, 19.5);
            const d = rng.range(13, 19.5);
            const h = rng.range(9, 26);
            const faces = [];
            if (li === 0 || rng.chance(0.5)) faces.push(sx > 0 ? '-x' : '+x');
            if (lj === 0 || rng.chance(0.5)) faces.push(sz > 0 ? '-z' : '+z');
            const wantEnterable = li === 0 && lj === 0 && enterableCount < 5 && rng.chance(0.62);
            if (wantEnterable) enterableCount++;
            const doorFace = sz > 0 ? '-z' : '+z';
            const cfg = {
              x: x, z: z, w: w, d: d, h: h, faces: faces,
              wall: rng.pick(WALLS), enterable: wantEnterable, doorFace: doorFace
            };
            addBuilding(world, cfg, rng);
            if (wantEnterable) {
              // interior cover + loot position
              const ix = x + rng.range(-w / 3, w / 3);
              const iz = z + rng.range(-d / 3, d / 3);
              addCrate(world, ix, iz, rng.range(0, TAU), rng);
              if (rng.chance(0.6)) addCrate(world, ix + 1.6, iz - 1.4, rng.range(0, TAU), rng);
              addCorpse(world, x + rng.range(-w / 3, w / 3), z + rng.range(-d / 3, d / 3), rng.range(0, TAU), rng);
              world.lootSpots.push({ x: ix - 1.6, z: iz + 1.2, indoor: true, near: { x: x, z: z } });
              world.stains.push({ x: ix + 0.8, z: iz + 0.6, size: rng.range(1.6, 2.8), type: 'pool' });
              const lamp = new THREE.PointLight(0xffcfa0, 0.6, 9, 2);
              lamp.position.set(x, h - 0.6, z);
              world.addLight(lamp, 0.65);
              world.flickerList.push({
                light: lamp, base: 0.65, phase: Math.random() * 100,
                speed: rng.range(0.4, 2.6), broken: true
              });
            } else if (rng.chance(0.4)) {
              world.lootSpots.push({ x: x + rng.range(w / 2 + 2, w / 2 + 5) * (sx > 0 ? -1 : 1), z: z, indoor: false });
            }
          }
        }
      }
    }
    // courtyards / alleys: rubble and dead trees where buildings were skipped
    for (let i = 0; i < 7; i++) {
      const x = rng.range(-HALF + 6, HALF - 6);
      const z = rng.range(-HALF + 6, HALF - 6);
      addRubble(world, x, z, rng.range(1.2, 2.6), rng);
    }
    for (let i = 0; i < 9; i++) {
      addDeadTree(world, rng.range(-HALF + 5, HALF - 5), rng.range(-HALF + 5, HALF - 5), rng);
    }
  }

