      if (rng.chance(0.6)) addCar(world, z + rng.range(-3, 3), -curbX - rng.range(0, 1.2), Math.PI / 2 + rng.range(-0.16, 0.16), rng);
      if (rng.chance(0.6)) addCar(world, z + rng.range(-3, 3), curbX + rng.range(0, 1.2), -Math.PI / 2 + rng.range(-0.16, 0.16), rng);
    }
