    }
    for (let i = 0; i < 8; i++) {
      const a = rng.range(0, TAU), r = rng.range(14, HALF - 6);
      addDumpster(world, Math.cos(a) * r, Math.sin(a) * r, rng.range(0, TAU), rng);
    }
    for (let i = 0; i < 18; i++) {
      const a = rng.range(0, TAU), r = rng.range(13, HALF - 4);
      addCrate(world, Math.cos(a) * r, Math.sin(a) * r, rng.range(0, TAU), rng);
    }
    // chain-link fencing sealing a couple of alleys (with gaps to fight through)
    addFence(world, 30, -30, 14, 0, rng);
    addFence(world, -30, 30, 14, 0, rng);
    addFence(world, 30, 30, 14, Math.PI / 2, rng);
    addFence(world, -30, -30, 14, Math.PI / 2, rng);

    for (let i = 0; i < 14; i++) {
      const a = rng.range(0, TAU), r = rng.range(11, HALF - 3);
      addCorpse(world, Math.cos(a) * r, Math.sin(a) * r, rng.range(0, TAU), rng);
    }
    for (let i = 0; i < 10; i++) {
      const a = rng.range(0, TAU), r = rng.range(10, HALF - 3);
      addDebris(world, Math.cos(a) * r, Math.sin(a) * r, rng.range(2, 5), rng);
      world.stains.push({ x: Math.cos(a) * r * 0.95, z: Math.sin(a) * r * 0.95, size: rng.range(1.2, 2.6), type: rng.chance(0.4) ? 'pool' : 'splat' });
    }
  }
