  /* ----------------------------------------------------- world state --- */
  /**
   * Create the world. Returns an object with the collision grid, surface
   * map, light pool and spawn points used by the rest of the game.
   */
  function create(scene, opts) {
    opts = opts || {};
    const world = {
      grid: new Z3.Grid(8),
      cityGroup: new THREE.Group(),
      surfaces: [],       // {minX,maxX,minZ,maxZ,type} for footstep sounds
      sidewalks: [],      // raised slabs (ground height)
      stains: [],         // pre-placed blood decals
      lootSpots: [],
      spawnPoints: [],
      firePoints: [],     // burning barrels (particle emitters)
      flickerList: [],
      loops: [],          // per-frame cosmetic callbacks
      lightSources: [],
      lightPool: [],
      bounds: { min: -HALF - 4, max: HALF + 4 },
      lightning: 0,
      lightningTimer: Z3.rand(18, 45),
      half: HALF,
      roadWidth: ROAD_W,
      _lightTimer: 0,
      _buf: []
    };
    scene.add(world.cityGroup);

    const rng = Z3.Rng(opts.seed === undefined ? 20250916 : opts.seed);

    /** Register a light source; the pool activates the nearest ones only. */
    world.addLight = function (holder, base) {
      const spec = {
        holder: holder,
        base: base === undefined ? 1 : base,
        dist: holder.distance || 22,
        pos: holder.position.clone ? holder.position.clone() : new THREE.Vector3(0, 2, 0),
        color: holder.color && holder.color.getHex ? holder.color.getHex() : 0xffd9a0,
        intensity: 0
      };
      if (holder.isObject3D && holder.parent === null && !holder.isPointLight) { /* keep simple */ }
      this.lightSources.push(spec);
      return spec;
    };

    world.surfaceAt = function (x, z) {
      const s = this.surfaces;
      for (let i = s.length - 1; i >= 0; i--) {
        const r = s[i];
        if (x > r.minX && x < r.maxX && z > r.minZ && z < r.maxZ) return r.type;
      }
      return 'dirt';
    };
    world.groundY = function (x, z) {
      const s = this.sidewalks;
      for (let i = 0; i < s.length; i++) {
        const r = s[i];
        if (x > r.minX && x < r.maxX && z > r.minZ && z < r.maxZ) return SW_Y;
      }
      return 0;
    };
    /** True when a circle fits without overlapping a solid collider. */
    world.isFree = function (x, z, r, ignoreBelow) {
      const buf = this.grid.query(x, z, r, this._buf);
      for (let i = 0; i < buf.length; i++) {
        const b = buf[i];
        if (!b.solid) continue;
        if (ignoreBelow && b.maxY <= ignoreBelow) continue;
        if (x > b.minX - r && x < b.maxX + r && z > b.minZ - r && z < b.maxZ + r) return false;
      }
      return true;
    };

    buildGround(world);
    buildPerimeter(world, rng);
    buildCity(world, rng);
    buildProps(world, rng);

    // zombie spawn points: road ends, alley mouths and the dark corners
    const ends = [
      { x: 0, z: -(HALF - 6) }, { x: 0, z: HALF - 6 },
      { x: -(HALF - 6), z: 0 }, { x: HALF - 6, z: 0 }
    ];
    for (let i = 0; i < ends.length; i++) world.spawnPoints.push(ends[i]);
    const near = ROAD_W / 2 + SW_W + 2.2;
    for (let i = -3; i <= 3; i++) {
      if (i === 0) continue;
      const t = i * 15;
      world.spawnPoints.push({ x: -near, z: t });
      world.spawnPoints.push({ x: near, z: t + 7 });
      world.spawnPoints.push({ x: t, z: -near });
      world.spawnPoints.push({ x: t + 7, z: near });
    }
    for (let i = 0; i < 10; i++) {
      const a = rng.range(0, TAU), r = rng.range(HALF - 14, HALF - 4);
      world.spawnPoints.push({ x: Math.cos(a) * r, z: Math.sin(a) * r });
    }

    // light pool: a fixed number of real point lights that follow the
    // nearest registered sources (keeps shader cost constant)
    const POOL = opts.lightPool || 6;
    for (let i = 0; i < POOL; i++) {
      const l = new THREE.PointLight(0xffd9a0, 0, 24, 2);
      l.castShadow = false;
      l.position.set(0, -50, 0);
      scene.add(l);
      world.lightPool.push(l);
    }

    world.update = function (dt, camPos) {
      // cosmetic callbacks (fire flicker etc.)
      for (let i = 0; i < this.loops.length; i++) this.loops[i](dt);
      // broken lamps stutter, working ones hum quietly
      const t = performance.now() * 0.001;
      for (let i = 0; i < this.flickerList.length; i++) {
        const f = this.flickerList[i];
        let v = 1;
        if (f.broken) {
          const n = Math.sin(t * f.speed * 6 + f.phase) * Math.sin(t * f.speed * 17.3 + f.phase * 1.7);
          v = n > 0.15 ? 1 : (Math.random() < 0.25 ? 0.85 : 0.08);
        } else {
          v = 0.94 + Math.sin(t * f.speed + f.phase) * 0.03 + Math.random() * 0.03;
        }
        f.light.intensity = f.base * v;
        if (f.lamp && f.lamp.material) {
          const c = 0.25 + 0.75 * v;
          f.lamp.material.color.setRGB(c, c * 0.94, c * 0.76);
        }
      }
      // assign the light pool to the nearest sources
      this._lightTimer -= dt;
      if (this._lightTimer <= 0) {
        this._lightTimer = 0.2;
        const src = this.lightSources;
        const px = camPos.x, pz = camPos.z;
        for (let i = 0; i < src.length; i++) {
          const s = src[i];
          const dx = s.pos.x - px, dz = s.pos.z - pz;
          s._d = dx * dx + dz * dz;
        }
        src.sort(function (a, b) { return a._d - b._d; });
        for (let i = 0; i < this.lightPool.length; i++) {
          const pool = this.lightPool[i];
          const s = src[i];
          if (!s || s._d > 40 * 40) { pool.intensity = 0; continue; }
          const cur = s.holder.intensity || s.base;
          const fade = clamp(1 - Math.sqrt(s._d) / 40, 0, 1);
          pool.position.copy(s.pos);
          pool.color.setHex(s.color);
          pool.distance = s.dist;
          pool.intensity = cur * fade;
        }
      }
      // distant lightning storm on the horizon
      this.lightningTimer -= dt;
      if (this.lightningTimer <= 0) {
        this.lightningTimer = Z3.rand(22, 70);
        this.lightning = 1;
      }
      if (this.lightning > 0) this.lightning = Math.max(0, this.lightning - dt * 2.6);
    };

    return world;
  }

  Z3.World = { create: create, HALF: HALF, ROAD_W: ROAD_W, SW_Y: SW_Y, getTex: getTex };
