    const c = document.createElement('canvas');
    c.width = c.height = size;
    return c;
  }
  /** Smooth value noise (bilinear over a random lattice) in 0..1. */
  function noiseField(size, cells, rnd) {
    const g = new Float32Array(cells * cells);
    for (let i = 0; i < g.length; i++) g[i] = rnd();
    const out = new Float32Array(size * size);
    const step = size / cells;
    for (let y = 0; y < size; y++) {
      const gy = y / step, y0 = Math.floor(gy), ty = gy - y0;
      const sy = ty * ty * (3 - 2 * ty);
      for (let x = 0; x < size; x++) {
        const gx = x / step, x0 = Math.floor(gx), tx = gx - x0;
        const sx = tx * tx * (3 - 2 * tx);
        const i00 = (y0 % cells) * cells + (x0 % cells);
        const i10 = (y0 % cells) * cells + ((x0 + 1) % cells);
        const i01 = ((y0 + 1) % cells) * cells + (x0 % cells);
        const i11 = ((y0 + 1) % cells) * cells + ((x0 + 1) % cells);
        const a = g[i00] + (g[i10] - g[i00]) * sx;
        const b = g[i01] + (g[i11] - g[i01]) * sx;
        out[y * size + x] = a + (b - a) * sy;
      }
    }
    return out;
  }
  /** Multi-octave greyscale canvas from value noise. */
  function greyCanvas(size, seed, octaves, base) {
    const rnd = rngFor(seed);
