    let amp = 1, total = 0, cells = base || 4;
    for (let o = 0; o < (octaves || 4); o++) {
      const f = noiseField(size, cells, rnd);
      for (let i = 0; i < acc.length; i++) acc[i] += f[i] * amp;
      total += amp;
      amp *= 0.55;
      cells = Math.min(size, cells * 2);
    }
    const c = canvas(size);
    const ctx = c.getContext('2d');
    const img = ctx.createImageData(size, size);
    for (let i = 0; i < acc.length; i++) {
      const v = Math.max(0, Math.min(255, (acc[i] / total) * 255)) | 0;
      img.data[i * 4] = img.data[i * 4 + 1] = img.data[i * 4 + 2] = v;
