      ctx.fillRect(0, 0, size, size);
      const rows = 12, bw = size / 6, bh = size / rows;
      const tones = ['#7a5546', '#6d4a3d', '#845b48', '#5f4338', '#8a6350'];
      for (let r = 0; r < rows; r++) {
        const off = (r % 2) * bw * 0.5;
        for (let i = -1; i < 7; i++) {
          ctx.fillStyle = tones[(rnd() * tones.length) | 0];
          const x = i * bw + off + 1.5, y = r * bh + 1.5;
          ctx.fillRect(x, y, bw - 3, bh - 3);
        }
