      overlayNoise(ctx, size, 71, 0.6, 5);
      blobs(ctx, size, rnd, 22, ['#2b2622', '#3a332c'], 10, 45, 0.3);   // soot
      streak(ctx, size, rnd, 12, 'rgba(30,28,24,0.9)');
      speckles(ctx, size, rnd, 500, ['#332e28', '#9a7a66'], 0.5, 2, 0.3);
    }, { seed: 71, roughness: 0.94, height: function (s, r) { return greyCanvas(s, 73, 5, 12); } });
  }
