  function drawWindowGrid(ctx, size, rnd, emissive) {
    const cols = 3, rows = 1;
    const cw = size / cols, ch = size / rows;
    ctx.fillStyle = emissive ? '#000000' : '#3b3b3d';
    ctx.fillRect(0, 0, size, size);
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const x = c * cw + 6, y = r * ch + 10, w = cw - 12, h = ch - 20;
        const broken = rnd() < 0.14;
        if (emissive) {
          if (!broken && rnd() < 0.14) {
            ctx.fillStyle = ['#3a2a12', '#2b2f3a', '#43301a'][(rnd() * 3) | 0];
            ctx.fillRect(x, y, w, h);
            ctx.fillStyle = 'rgba(255,200,130,0.35)';
            ctx.fillRect(x + w * 0.2, y + h * 0.3, w * 0.6, h * 0.4);
          }
          continue;
        }
        // glass with a cold vertical reflection
        const g = ctx.createLinearGradient(x, y, x, y + h);
        g.addColorStop(0, '#2b3440');
        g.addColorStop(0.45, '#141a21');
        g.addColorStop(1, '#0d1116');
        ctx.fillStyle = g;
        ctx.fillRect(x, y, w, h);
        if (broken) {
          ctx.fillStyle = '#0a0c0f';
          ctx.fillRect(x, y, w, h);
          ctx.strokeStyle = 'rgba(190,205,220,0.5)';
          ctx.lineWidth = 1.2;
          for (let i = 0; i < 7; i++) {
            ctx.beginPath();
            const cx = x + rnd() * w, cy = y + rnd() * h;
            ctx.moveTo(cx, cy);
            ctx.lineTo(cx + rnd() * w * 0.4 - w * 0.2, cy + rnd() * h * 0.4 - h * 0.2);
            ctx.stroke();
          }
        } else {
          ctx.globalAlpha = 0.10 + rnd() * 0.12;
          ctx.fillStyle = '#9fb3c8';
          ctx.fillRect(x, y, w, h * 0.28);
          ctx.globalAlpha = 1;
        }
        // grime creeping up the glass
        ctx.globalAlpha = 0.35;
        ctx.fillStyle = '#1b1c1a';
        ctx.fillRect(x, y + h * 0.72, w, h * 0.28);
        ctx.globalAlpha = 1;
      }
    }
    if (!emissive) {
      // mullions / frames
      ctx.strokeStyle = 'rgba(64,66,68,0.95)';
      ctx.lineWidth = 10;
      for (let c = 1; c < cols; c++) {
        ctx.beginPath(); ctx.moveTo(c * cw, 0); ctx.lineTo(c * cw, size); ctx.stroke();
      }
      ctx.lineWidth = 16;
      ctx.beginPath(); ctx.moveTo(0, 6); ctx.lineTo(size, 6); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, size - 6); ctx.lineTo(size, size - 6); ctx.stroke();
      overlayNoise(ctx, size, 149, 0.35, 4);
    }
