   DEAD ZONE 3D  —  js/audio.js
   Every sound is synthesised at runtime with the Web Audio API: layered
   noise/oscillator voices, a generated impulse-response reverb for
   outdoor slapback and a generative ambient bed (wind, city drone,
   distant moans).  No audio files, works from file://.
   ===================================================================== */
window.Z3Audio = (function () {
  'use strict';
  const MAX_VOICES = 24;

  let ctx = null, master = null, sfxBus = null, ambBus = null, comp = null, verb = null, verbGain = null;
  let noise = null, pink = null, voices = 0;
  let enabled = true, masterVol = 0.85, sfxVol = 1.0, ambVol = 0.7;
  let amb = null, threat = 0, threatTarget = 0;

  function init() {
    if (ctx) return ctx;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    try {
      ctx = new AC();
    } catch (e) {
      return null;
    }
    comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -14;
    comp.knee.value = 12;
    comp.ratio.value = 5;
    comp.attack.value = 0.004;
    comp.release.value = 0.22;
    master = ctx.createGain();
    master.gain.value = masterVol;
    sfxBus = ctx.createGain();
    sfxBus.gain.value = sfxVol;
    ambBus = ctx.createGain();
    ambBus.gain.value = ambVol;
    sfxBus.connect(master);
    ambBus.connect(master);
    master.connect(comp);
    comp.connect(ctx.destination);

    // generated impulse response: outdoor slapback + long dark tail
    const len = Math.floor(ctx.sampleRate * 1.6);
    const ir = ctx.createBuffer(2, len, ctx.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const d = ir.getChannelData(ch);
      for (let i = 0; i < len; i++) {
        const t = i / len;
        d[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, 3.4) * (i < 40 ? 0.3 : 1);
      }
    }
    verb = ctx.createConvolver();
    verb.buffer = ir;
    verbGain = ctx.createGain();
    verbGain.gain.value = 0.5;
    verb.connect(verbGain);
    verbGain.connect(master);

    noise = makeNoise(2.0, 'white');
    pink = makeNoise(2.5, 'pink');
    return ctx;
  }

  function makeNoise(seconds, kind) {
    const n = Math.floor(ctx.sampleRate * seconds);
    const buf = ctx.createBuffer(1, n, ctx.sampleRate);
    const d = buf.getChannelData(0);
    let b0 = 0, b1 = 0, b2 = 0;
    for (let i = 0; i < n; i++) {
      const w = Math.random() * 2 - 1;
      if (kind === 'pink') {
        b0 = 0.99765 * b0 + w * 0.0990460;
        b1 = 0.96300 * b1 + w * 0.2965164;
        b2 = 0.57000 * b2 + w * 1.0526913;
        d[i] = (b0 + b1 + b2 + w * 0.1848) * 0.22;
      } else {
        d[i] = w;
      }
    }
    return buf;
  }

  function ready() {
    return !!(ctx && enabled);
  }
  function resume() {
    init();
    if (ctx && ctx.state === 'suspended') ctx.resume();
  }
  function spendVoice() {
    if (voices >= MAX_VOICES) return false;
    voices++;
    return true;
  }
  /** Route a source through optional lowpass + panner + gain into a bus. */
  function out(node, o, bus) {
    let chain = node;
    if (o.distance) {
      const lp = ctx.createBiquadFilter();
      lp.type = 'lowpass';
      lp.frequency.value = Math.max(450, 16000 * (1 - o.distance * 0.92));
      chain.connect(lp);
      chain = lp;
    }
    if (o.pan !== undefined && ctx.createStereoPanner) {
      const p = ctx.createStereoPanner();
      p.pan.value = Math.max(-1, Math.min(1, o.pan));
      chain.connect(p);
      chain = p;
    }
    const g = ctx.createGain();
    const dist = o.distance ? 1 - o.distance * 0.75 : 1;
    g.gain.value = (o.volume === undefined ? 1 : o.volume) * dist;
    chain.connect(g);
    g.connect(bus);
    g.connect(verb);
    return g;
  }
  function resumeVoice(dur) {
    const t = setTimeout(function () { voices = Math.max(0, voices - 1); }, (dur || 1) * 1000 + 60);
    if (t.unref) t.unref();
