    if (o.f1 !== undefined) s.frequency.exponentialRampToValueAtTime(Math.max(20, o.f1), o.t + o.dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, o.t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, o.gain || 0.3), o.t + (o.attack || 0.005));
    g.gain.exponentialRampToValueAtTime(0.0001, o.t + o.dur);
    s.connect(g);
    s.start(o.t);
    s.stop(o.t + o.dur + 0.02);
    return { src: s, gain: g };
  }
  function burst(o, bus) {
    const s = noiseSrc(o, bus);
    const f = ctx.createBiquadFilter();
    f.type = o.filter || 'lowpass';
    f.frequency.setValueAtTime(o.f0, o.t);
    if (o.f1 !== undefined) f.frequency.exponentialRampToValueAtTime(Math.max(40, o.f1), o.t + o.dur);
    f.Q.value = o.q || 1;
    s.connect(f);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, o.t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, o.gain || 0.4), o.t + (o.attack || 0.002));
    g.gain.exponentialRampToValueAtTime(0.0001, o.t + o.dur);
    f.connect(g);
