    setAmbientVolume: function (v) { ambVol = Math.max(0, Math.min(1, v)); if (ambBus) ambBus.gain.value = ambVol; },
    _ctx: function () { return ctx; },
    _sfxBus: function () { return sfxBus; },
    _ambBus: function () { return ambBus; },
    _noise: function () { return noise; },
    _pink: function () { return pink; },
    _out: out,
    _noiseSrc: noiseSrc,
