window.Z3 = window.Z3 || {};
(function (Z3) {
  'use strict';
  const clamp = Z3.clamp;
  const TAU = Z3.TAU;

  const VARIANTS = {
    walker: {
      hp: 105, speed: 1.15, runSpeed: 1.6, dmg: 12, scale: 1.0, sight: 20, hear: 1.0,
      xp: 10, rage: 0.35, skin: 0xa2a184
    },
    runner: {
      hp: 78, speed: 1.7, runSpeed: 4.0, dmg: 9, scale: 0.98, sight: 26, hear: 1.35,
      xp: 16, rage: 0.75, skin: 0x9c9a76
    },
    brute: {
      hp: 430, speed: 0.95, runSpeed: 1.5, dmg: 34, scale: 1.36, sight: 18, hear: 1.1,
      xp: 40, rage: 0.25, skin: 0x8a8567
    },
    crawler: {
      hp: 62, speed: 0.8, runSpeed: 1.5, dmg: 8, scale: 1.0, sight: 14, hear: 1.2,
      xp: 12, rage: 0.5, crawl: true, skin: 0x96917a
    }
  };
  const SKINS = [0xa2a184, 0x8f8c6d, 0xb0ab92, 0x7f8672, 0x9c8f78];
  const CLOTH = [0x4c4a42, 0x3f4750, 0x5a4a3c, 0x45443f, 0x604c48, 0x39424a];
  const matSets = [];

  function buildMaterialSets() {
    if (matSets.length) return matSets;
    for (let i = 0; i < 3; i++) {
      matSets.push({
        skin: Z3.material('fleshSkin', SKINS[i * 2 % SKINS.length], 1, 1, { roughness: 0.86 }),
        shirt: Z3.material('cloth', CLOTH[i * 2 % CLOTH.length], 1, 1, { roughness: 0.96 }),
        pants: Z3.material('cloth', CLOTH[(i * 2 + 2) % CLOTH.length], 1, 1, { roughness: 0.96 }),
        hair: Z3.material('cloth', 0x2a2622, 1, 1, { roughness: 1, color: 0x342f28 })
      });
    }
    return matSets;
  }

  /* ------------------------------------------------------- body build -- */
  function limb(mat, w, h, d, x, y, z) {
    const m = new THREE.Mesh(Z3.GEO.box, mat);
    m.scale.set(w, h, d);
    m.position.set(x || 0, y || 0, z || 0);
    m.castShadow = true;
    return m;
  }
  function pivot(parent, x, y, z) {
    const g = new THREE.Group();
    g.position.set(x || 0, y || 0, z || 0);
    parent.add(g);
    return g;
  }

  function buildBody(z, mats) {
    const v = z.def;
    const s = v.scale;
    const crawl = !!v.crawl;
    const root = new THREE.Group();
    const hips = pivot(root, 0, crawl ? 0.36 : 1.0, 0);
    const torso = pivot(hips, 0, 0, 0);
    const torsoMesh = limb(mats.shirt, 0.46 * s, 0.58 * s, 0.27 * s, 0, 0.29 * s, 0);
    torso.add(torsoMesh);
    torso.add(limb(mats.pants, 0.42 * s, 0.22 * s, 0.26 * s, 0, -0.05 * s, 0));
    const neck = pivot(torso, 0, 0.6 * s, 0);
    const head = limb(mats.skin, 0.24 * s, 0.27 * s, 0.26 * s, 0, 0.14 * s, 0);
    const hair = limb(mats.hair, 0.25 * s, 0.09 * s, 0.27 * s, 0, 0.26 * s, -0.01 * s);
    neck.add(head, hair);

    // jaw for the screamers (cosmetic detail that sells the model)
    const jaw = limb(mats.skin, 0.16 * s, 0.07 * s, 0.12 * s, 0, 0.03 * s, 0.13 * s);
    neck.add(jaw);

    const arms = [];
    for (let i = 0; i < 2; i++) {
      const side = i === 0 ? -1 : 1;
      const sh = pivot(torso, side * 0.29 * s, 0.49 * s, 0);
      const upper = limb(mats.shirt, 0.12 * s, 0.36 * s, 0.13 * s, 0, -0.18 * s, 0);
      const el = pivot(sh, 0, -0.36 * s, 0);
      const fore = limb(mats.skin, 0.11 * s, 0.34 * s, 0.11 * s, 0, -0.17 * s, 0);
      const hand = limb(mats.skin, 0.11 * s, 0.12 * s, 0.12 * s, 0, -0.36 * s, 0.01 * s);
      el.add(fore, hand);
      sh.add(upper);
      arms.push({ shoulder: sh, elbow: el, upper: upper, fore: fore, hand: hand, side: side });
    }
    const legs = [];
    for (let i = 0; i < 2; i++) {
      const side = i === 0 ? -1 : 1;
      const hip = pivot(hips, side * 0.14 * s, 0, 0);
      const upper = limb(mats.pants, 0.15 * s, 0.45 * s, 0.15 * s, 0, -0.22 * s, 0);
      const knee = pivot(hip, 0, -0.45 * s, 0);
      const lower = limb(mats.pants, 0.13 * s, 0.43 * s, 0.13 * s, 0, -0.21 * s, 0);
      const foot = limb(mats.hair, 0.14 * s, 0.09 * s, 0.3 * s, 0, -0.43 * s, 0.08 * s);
      knee.add(lower, foot);
      hip.add(upper);
      legs.push({ hip: hip, knee: knee, upper: upper, lower: lower, foot: foot, side: side });
    }

    z.root = root;
    z.hips = hips;
    z.torso = torso;
    z.torsoMesh = torsoMesh;
    z.neck = neck;
    z.head = head;
    z.jaw = jaw;
    z.arms = arms;
    z.legs = legs;

    torsoMesh.userData.zone = 'torso';
    head.userData.zone = 'head';
    hair.userData.zone = 'head';
    const parts = [torsoMesh, head, hair];
    for (let i = 0; i < 2; i++) {
      arms[i].upper.userData.zone = 'limb';
      arms[i].fore.userData.zone = 'limb';
      arms[i].hand.userData.zone = 'limb';
      parts.push(arms[i].upper, arms[i].fore, arms[i].hand);
      if (!crawl) {
        legs[i].upper.userData.zone = 'leg';
        legs[i].lower.userData.zone = 'leg';
        parts.push(legs[i].upper, legs[i].lower);
      } else {
        for (const k in legs[i]) if (legs[i][k] && legs[i][k].isObject3D) legs[i][k].visible = false;
