    this.yaw = Math.random() * TAU;
    this.hp = this.def.hp * (opts.hpScale || 1);
    this.maxHp = this.hp;
    this.dmgScale = opts.dmgScale || 1;
    this.speedScale = opts.speedScale || 1;
    this.state = 'idle';
    this.stateT = Z3.rand(0.2, 2.5);
    this.attackCd = 0;
    this.gait = Math.random() * TAU;
    this.moveSpeed = 0;
    this.alert = 0;
    this.target = null;
    this.lostT = 0;
    this.percT = Math.random() * 0.4;
    this.growlT = Z3.rand(3, 12);
    this.stagger = 0;
    this.speedMul = 1;
    this.limbHp = { arm0: 34, arm1: 34, leg0: 46, leg1: 46 };
    this.dead = false;
    this.deadT = 0;
    this.fallAxis = new THREE.Vector3(Math.random() - 0.5, 0, Math.random() - 0.5).normalize();
    this.fallDir = Math.random() < 0.5 ? 1 : -1;
    this.bob = 0;
    this.bloodPooled = false;
    this.sep = new THREE.Vector3();
    this.hurtFlash = 0;
    buildBody(this);
    this.root.position.copy(this.pos);
    this.root.rotation.y = this.yaw;
    const scale = this.quirk.size * (opts.scaleMul || 1);
    this.root.scale.setScalar(scale);
    this.height = 1.85 * scale;
    world.zombieGroup.add(this.root);
  }

  /* ------------------------------------------------------ animation ----- */
  Zombie.prototype.animate = function (dt) {
    const v = this.def;
    const a = this.arms, l = this.legs;
    if (this.dead) {
      // ragdoll-lite: topple over with a little bounce, limbs go limp
      this.deadT += dt;
      if (this.deadT < 1.4) {
        const t = Math.min(1, this.deadT / 1.1);
        const ease = 1 - Math.pow(1 - t, 3);
        this.root.rotation.z = this.fallAxis.z * ease * 1.5 * this.fallDir;
        this.root.rotation.x = -this.fallAxis.x * ease * 1.5 * this.fallDir;
        this.body.position.y = Math.max(0.16, (v.crawl ? 0.42 : 1.0) * (1 - ease * 0.82));
      }
      for (let i = 0; i < 2; i++) {
        a[i].shoulder.rotation.x = Z3.damp(a[i].shoulder.rotation.x, (i ? 0.9 : -0.7), 3, dt);
        a[i].elbow.rotation.x = Z3.damp(a[i].elbow.rotation.x, -0.4, 3, dt);
        if (!l[i].missing) {
          l[i].hip.rotation.x = Z3.damp(l[i].hip.rotation.x, 0.2, 2.4, dt);
          l[i].knee.rotation.x = Z3.damp(l[i].knee.rotation.x, -0.5, 2.4, dt);
        }
      }
      this.torso.rotation.x = Z3.damp(this.torso.rotation.x, 0.1, 2.5, dt);
      this.neck.rotation.x = Z3.damp(this.neck.rotation.x, 0.35, 2.5, dt);
      return;
    }
    // gait phase advances with actual movement speed
    const speed = this.moveSpeed;
    this.gait += dt * (v.gaitRate + speed * 2.1) * (this.speedMul);
    const swing = Math.sin(this.gait);
    const swing2 = Math.cos(this.gait);
    const amp = v.gaitAmp * (0.35 + Math.min(1, speed / 1.6) * 0.9);
    const stagger = this.stagger > 0 ? this.stagger : 0;

    for (let i = 0; i < 2; i++) {
      const sgn = i === 0 ? 1 : -1;
      const ph = this.gait * (this.quirk.sway) + (i ? Math.PI : 0) + this.quirk.phase;
      const sw = Math.sin(ph);
      if (!l[i].missing) {
        l[i].hip.rotation.x = sw * amp * sgn;
        l[i].knee.rotation.x = -Math.max(0, Math.sin(ph + 1.1)) * amp * 1.5 - 0.15;
      }
      let armAmp = amp * 0.8;
      let base = 0.1;
      if (v.dragArm && i === 0) {
        // walkers drag one dead arm
        a[i].shoulder.rotation.x = Z3.damp(a[i].shoulder.rotation.x, 0.85 + Math.sin(this.gait * 0.6) * 0.08, 4, dt);
        a[i].elbow.rotation.x = -0.55;
        a[i].shoulder.rotation.z = 0.25 * (i === 0 ? -1 : 1);
        continue;
      }
      a[i].shoulder.rotation.x = -sw * armAmp + base;
      a[i].elbow.rotation.x = -0.35 - Math.max(0, sw) * 0.35;
      a[i].shoulder.rotation.z = (i === 0 ? -1 : 1) * (0.12 + (1 - Math.min(1, speed / 2)) * 0.22);
    }
    // body: lean, sway, bob, stagger wobble
    const lean = v.lean + Math.min(1, speed / 3) * 0.22 + stagger * 0.5;
    this.torso.rotation.x = Z3.damp(this.torso.rotation.x, lean, 6, dt);
    this.torso.rotation.z = swing2 * 0.06 * this.quirk.sway + stagger * 0.3;
    this.torso.rotation.y = swing * 0.08;
    this.bob += dt * (2.2 + speed * 2.4);
    const hipY = v.crawl ? 0.42 : 1.0;
    this.body.position.y = hipY + Math.abs(Math.sin(this.bob)) * 0.035 * (v.crawl ? 0.4 : 1) + (v.crawl ? -(1 - Math.min(1, speed)) * 0.02 : 0);
    if (v.crawl) {
      // dragging itself along the ground, arms pulling alternately
      for (let i = 0; i < 2; i++) {
        const ph = this.bob * 2 + (i ? Math.PI : 0);
        this.arms[i].shoulder.rotation.x = -0.9 - Math.sin(ph) * 0.5;
        this.arms[i].elbow.rotation.x = -0.7;
      }
      this.root.position.y = this.pos.y + 0.02;
    }
    // head: droop, tilt, flinch wobble
    const headBase = v.crawl ? 0.6 : (0.18 + Math.min(1, speed / 3) * 0.18);
    this.neck.rotation.x = Z3.damp(this.neck.rotation.x, headBase + Math.sin(this.gait * 0.7) * 0.05 + stagger * 0.35, 5, dt);
    this.neck.rotation.z = this.quirk.headTilt + Math.sin(this.gait * 0.5) * 0.05;
    this.neck.rotation.y = Math.sin(this.gait * 0.35 + this.quirk.phase) * 0.12;
    if (this.hurtFlash > 0) this.hurtFlash -= dt;
