  /* -------------------------------------------------------- movement --- */
  /** Obstacle-aware step: tries the desired heading then fans out. */
  Zombie.prototype.steer = function (dt, dirX, dirZ, speed) {
    const step = speed * dt;
    if (step <= 0.0001) { this.moveSpeed = 0; return; }
    const cands = [0, 0.4, -0.4, 0.85, -0.85, 1.3, -1.3, 1.8, -1.8, 2.5, -2.5];
    let moved = false;
    for (let i = 0; i < cands.length; i++) {
      const a = cands[i] * this.turnBias;
      const c = Math.cos(a), s = Math.sin(a);
      const nx = dirX * c - dirZ * s;
      const nz = dirX * s + dirZ * c;
      const px = this.pos.x + nx * step;
      const pz = this.pos.z + nz * step;
      if (!this.world.isFree(px, pz, 0.44)) continue;
      this.pos.x = px;
      this.pos.z = pz;
      this.desiredYaw = Math.atan2(nx, nz);
      moved = true;
      this.blocked = 0;
      break;
    }
    if (!moved) {
      this.blocked = (this.blocked || 0) + dt;
      this.moveSpeed *= 0.5;
      // gives up on the straight path and re-routes
      if (this.blocked > 0.5 && this.state === 'chase') {
        this.turnBias = this.turnBias > 0 ? -1 : 1;
        this.blocked = 0;
      }
    } else {
      this.moveSpeed = speed;
    }
  };

  /** Keep a little personal space so the horde does not collapse into one blob. */
  Zombie.prototype.separate = function (dt) {
    const list = this.manager.neighbours(this.pos.x, this.pos.z, 1.2, this);
    let sx = 0, sz = 0, k = 0;
    for (let i = 0; i < list.length; i++) {
      const o = list[i];
      if (o.dead) continue;
      const dx = this.pos.x - o.pos.x, dz = this.pos.z - o.pos.z;
      const d2 = dx * dx + dz * dz;
      if (d2 < 1e-5) {
        sx += Math.random() - 0.5;
        sz += Math.random() - 0.5;
        k++;
        continue;
      }
      const d = Math.sqrt(d2);
      const w = (1.2 - d) / 1.2;
      sx += (dx / d) * w;
      sz += (dz / d) * w;
      k++;
    }
    if (k > 0) {
      this.pos.x += sx * dt * 2.2;
      this.pos.z += sz * dt * 2.2;
    }
    const b = this.world.bounds;
    this.pos.x = clamp(this.pos.x, b.min, b.max);
    this.pos.z = clamp(this.pos.z, b.min, b.max);
  };

  Zombie.prototype.perceive = function (player, dist, game) {
    const def = this.def;
    // sight: distance + line of sight (zombies see the flashlight from further away)
    const sightRange = def.sight * (player.flashlightOn ? 1.35 : 1) * (player.crouching ? 0.82 : 1);
    if (dist < sightRange) {
      const blocked = this.world.grid.lineBlocked(this.pos.x, this.pos.z, player.pos.x, player.pos.z, 1.55);
      const ahead = Math.cos(Z3.angleDelta(this.yaw, Math.atan2(player.pos.x - this.pos.x, player.pos.z - this.pos.z)));
      if (!blocked && (ahead > 0.15 || dist < 6)) {
        this.alert = 1;
        this.lostT = 0;
        this.target = { x: player.pos.x, z: player.pos.z };
        if (this.state === 'idle' || this.state === 'wander') {
          this.set(game, 'chase', 0);
          if (this.type === 'runner') game.sfxAt('zombieScream', this.pos, { volume: 0.5 });
          else if (Z3.chance(0.25)) game.sfxAt('zombieGrowl', this.pos, { volume: 0.4 });
        }
        return;
      }
    }
    if (this.state === 'chase') {
      this.lostT += 0.25;
      if (this.lostT > 3.2) {
        // lost the player: search the last known position
        this.alert = 0.5;
        this.set(game, 'investigate', Z3.rand(4, 8));
      } else {
        this.target = { x: player.pos.x, z: player.pos.z };
      }
    }
  };

  Zombie.prototype.set = function (game, state, time) {
    this.state = state;
    this.stateT = time === undefined ? 3 : time;
    void game;
  };
