  /* ------------------------------------------------------- main update - */
  Zombie.prototype.update = function (dt, player, game) {
    const def = this.def;
    if (this.dead) {
      this.animate(dt);
      this.sync(dt);
      return;
    }
    this.attackCd = Math.max(0, this.attackCd - dt);
    this.stateT -= dt;
    const dx = player.pos.x - this.pos.x;
    const dz = player.pos.z - this.pos.z;
    const dist = Math.max(0.0001, Math.hypot(dx, dz));
    const dirX = dx / dist, dirZ = dz / dist;
    const toPlayer = Math.atan2(dirX, dirZ);

    this.percT -= dt;
    if (this.percT <= 0) {
      this.percT = 0.2 + Math.random() * 0.3;
      this.perceive(player, dist, game);
    }
    // vocalisations (runners chatter, brutes rumble, the horde answers screams)
    this.growlT -= dt;
    if (this.growlT <= 0) {
      const aware = this.alert > 0.5;
      this.growlT = Z3.rand(4, 15) * (aware ? 0.35 : 1);
      game.sfxAt('zombieGrowl', this.pos, {
        volume: aware ? 0.6 : 0.3,
        rate: this.type === 'brute' ? 0.68 : (this.type === 'runner' ? 1.15 : 1)
      });
    }

    let mx = 0, mz = 0, speed = 0;
    switch (this.state) {
      case 'idle':
        this.moveSpeed *= 0.8;
        if (this.alert > 0.5) {
          this.set(game, 'chase', 0);
        } else {
          this.desiredYaw = this.yaw;
          if (this.stateT <= 0) {
            if (Z3.chance(0.6)) {
              this.wander = {
                x: clamp(this.pos.x + (Math.random() - 0.5) * 18, -this.world.half + 2, this.world.half - 2),
                z: clamp(this.pos.z + (Math.random() - 0.5) * 18, -this.world.half + 2, this.world.half - 2)
              };
              this.set(game, 'wander', Z3.rand(6, 15));
            } else {
              this.set(game, 'idle', Z3.rand(1.5, 5));
            }
          }
        }
        break;
      case 'wander': {
        if (this.alert > 0.5) { this.set(game, 'chase', 0); break; }
        const t = this.wander;
        if (!t || this.stateT <= 0) { this.set(game, 'idle', Z3.rand(1, 4)); break; }
        const tx = t.x - this.pos.x, tz = t.z - this.pos.z;
        const d = Math.hypot(tx, tz);
        if (d < 1.2) { this.set(game, 'idle', Z3.rand(1, 4)); break; }
        mx = tx / d; mz = tz / d;
        speed = def.speed * 0.55 * this.speedScale;
        break;
      }
      case 'investigate': {
        const t = this.target || this.wander;
        if (!t || this.stateT <= 0) { this.set(game, 'idle', Z3.rand(1, 3)); break; }
        const tx = t.x - this.pos.x, tz = t.z - this.pos.z;
        const d = Math.hypot(tx, tz);
        if (d < 1.8) { this.set(game, 'idle', Z3.rand(1, 3)); break; }
        mx = tx / d; mz = tz / d;
        speed = def.speed * 0.9 * this.speedScale;
        break;
      }
      case 'chase': {
        const tx = (this.target ? this.target.x : player.pos.x) - this.pos.x;
        const tz = (this.target ? this.target.z : player.pos.z) - this.pos.z;
        const d = Math.max(0.001, Math.hypot(tx, tz));
        if (dist > 1.85) {
          mx = tx / d; mz = tz / d;
          speed = def.chaseSpeed * this.speedScale * this.speedMul;
        } else {
          this.moveSpeed *= 0.7;
          this.desiredYaw = toPlayer;
        }
        if (dist < 2.0 && this.attackCd <= 0 && Math.abs(Z3.angleDelta(this.yaw, toPlayer)) < 1.1) {
          this.state = 'attack';
          this.attackT = 0;
          this.attackHit = false;
          this.stateT = 0.95;
        }
        break;
      }
      case 'attack':
        this.updateAttack(dt, player, dist, toPlayer, game);
        break;
      case 'stagger':
        this.moveSpeed *= 0.86;
        if (this.stateT <= 0) this.set(game, this.alert > 0.6 ? 'chase' : 'investigate', Z3.rand(2, 5));
        break;
    }

    if (speed > 0) this.steer(dt, mx, mz, speed);
    else this.moveSpeed *= 0.75;
    this.separate(dt);

