{"toolCallId":"call_2fc536a1fe504701a1e57cb2","toolName":"editor","input":{"new_text":"/* =====================================================================
   DEAD ZONE 3D  —  js/zombie.js
   Articulated humanoid zombies: per-limb hitboxes and damage zones,
   dismemberment, procedural gait animation, horde AI (idle / wander /
   investigate / chase / attack / death) and a manager handling spawning,
   spatial queries, separation and corpse clean-up.
   Requires utils.js + world.js (Z3.GEO, Z3.material, Z3.Grid).
   ===================================================================== */
window.Z3 = window.Z3 || {};
(function (Z3) {
  'use strict';
  const clamp = Z3.clamp;
  const TAU = Z3.TAU;

  const VARIANTS = {
    walker: {
      hp: 105, speed: 1.05, chaseSpeed: 1.85, dmg: 11, scale: 1.0, sight: 21,
      hear: 1.0, xp: 10, lean: 0.26, gaitAmp: 0.55, gaitRate: 1.6, dragArm: true, crawl: false
    },
    runner: {
      hp: 78, speed: 1.6, chaseSpeed: 4.0, dmg: 8, scale: 0.97, sight: 27,
      hear: 1.35, xp: 16, lean: 0.52, gaitAmp: 0.95, gaitRate: 2.4, dragArm: false, crawl: false
    },
    brute: {
      hp: 430, speed: 0.92, chaseSpeed: 1.65, dmg: 32, scale: 1.36, sight: 19,
      hear: 1.1, xp: 40, lean: 0.16, gaitAmp: 0.4, gaitRate: 1.15, dragArm: false, crawl: false
    },
    crawler: {
      hp: 62, speed: 0.8, chaseSpeed: 1.8, dmg: 7, scale: 1.0, sight: 15,
      hear: 1.2, xp: 12, lean: 0.72, gaitAmp: 0.8, gaitRate: 2.0, dragArm: false, crawl: true
    }
  };
  const SKINS = [0xa2a184, 0x8f8c6d, 0xb0ab92, 0x7f8672, 0x9c8f78];
  const CLOTH = [0x4c4a42, 0x3f4750, 0x5a4a3c, 0x45443f, 0x604c48, 0x39424a];
  const matPool = [];

  /** Shared materials so every zombie batches into few draw calls. */
  function zombieMaterials(index) {
    const i = ((index | 0) % SKINS.length + SKINS.length) % SKINS.length;
    if (matPool[i]) return matPool[i];
    const c = (i * 3) % CLOTH.length;
    const set = {
      skin: Z3.material('fleshSkin', SKINS[i], 1, 1, { roughness: 0.88 }),
      shirt: Z3.material('cloth', CLOTH[c], 1, 1, { roughness: 0.96 }),
      pants: Z3.material('cloth', CLOTH[(c + 3) % CLOTH.length], 1, 1, { roughness: 0.96 }),
      shoe: Z3.material('cloth', 0x2c2a28, 1, 1, { roughness: 1, color: 0x33302c })
    };
    matPool[i] = set;
    return set;
  }

  function limbMesh(mat, w, h, d, cy) {
    const m = new THREE.Mesh(Z3.GEO.box, mat);
    m.scale.set(w, h, d);
    m.position.y = cy || 0;
    m.castShadow = true;
    m.receiveShadow = false;
    return m;
  }
  function pivot(parent, x, y, z) {
    const g = new THREE.Group();
    g.position.set(x || 0, y || 0, z || 0);
    parent.add(g);
    return g;
  }

  /** Builds the body; every mesh stores its damage zone + owner zombie. */
  function buildBody(z) {
    const v = z.def;
    const m = z.mats;
    const s = v.scale;
    const root = new THREE.Group();
    const hipY = v.crawl ? 0.42 : 1.0;
    const body = pivot(root, 0, hipY, 0);
    const torso = pivot(body, 0, 0, 0);
    const chest = limbMesh(m.shirt, 0.46 * s, 0.58 * s, 0.27 * s, 0.29 * s);
    torso.add(chest);
    body.add(limbMesh(m.pants, 0.42 * s, 0.24 * s, 0.26 * s, -0.06 * s));
    const neck = pivot(torso, 0, 0.6 * s, 0);
    const head = limbMesh(m.skin, 0.24 * s, 0.28 * s, 0.26 * s, 0.14 * s);
    neck.add(head);
    neck.add(limbMesh(m.shoe, 0.25 * s, 0.1 * s, 0.27 * s, 0.27 * s));

    const arms = [];
    for (let i = 0; i < 2; i++) {
      const side = i === 0 ? -1 : 1;
      const shoulder = pivot(torso, side * 0.29 * s, 0.49 * s, 0);
      const upper = limbMesh(m.shirt, 0.12 * s, 0.36 * s, 0.13 * s, -0.18 * s);
      const elbow = pivot(shoulder, 0, -0.36 * s, 0);
      const fore = limbMesh(m.skin, 0.11 * s, 0.34 * s, 0.11 * s, -0.17 * s);
      const hand = limbMesh(m.skin, 0.11 * s, 0.13 * s, 0.12 * s, -0.37 * s);
      shoulder.add(upper);
      elbow.add(fore, hand);
      arms.push({
        shoulder: shoulder, elbow: elbow, upper: upper, fore: fore, hand: hand,
        side: side, upperMesh: upper, foreMesh: fore, missing: false
      });
    }
    const legs = [];
    for (let i = 0; i < 2; i++) {
      const side = i === 0 ? -1 : 1;
      const hip = pivot(body, side * 0.14 * s, 0, 0);
      const upper = limbMesh(m.pants, 0.15 * s, 0.45 * s, 0.15 * s, -0.22 * s);
      const knee = pivot(hip, 0, -0.45 * s, 0);
      const lower = limbMesh(m.pants, 0.13 * s, 0.43 * s, 0.13 * s, -0.21 * s);
      const foot = limbMesh(m.shoe, 0.14 * s, 0.1 * s, 0.3 * s, -0.43 * s);
      foot.position.z = 0.08 * s;
      hip.add(upper);
      knee.add(lower, foot);
      legs.push({ hip: hip, knee: knee, upper: upper, lower: lower, foot: foot, side: side, missing: false });
    }

    z.root = root;
    z.body = body;
    z.torso = torso;
    z.chest = chest;
    z.neck = neck;
    z.head = head;
    z.arms = arms;
    z.legs = legs;

    chest.userData.zone = 'torso';
    head.userData.zone = 'head';
    const parts = [chest, head];
    for (let i = 0; i < 2; i++) {
      arms[i].upperMesh.userData.zone = 'limb';
      arms[i].foreMesh.userData.zone = 'limb';
      arms[i].hand.userData.zone = 'limb';
      parts.push(arms[i].upperMesh, arms[i].foreMesh, arms[i].hand);
      if (v.crawl) {
        legs[i].upper.visible = false;
        legs[i].lower.visible = false;
        legs[i].foot.visible = false;
        legs[i].missing = true;
      } else {
        legs[i].upper.userData.zone = 'leg';
        legs[i].lower.userData.zone = 'leg';
        parts.push(legs[i].upper, legs[i].lower);
      }
    }
    for (let i = 0; i < parts.length; i++) parts[i].userData.zombie = z;
    z.hitParts = parts;
    z.quirk = {
      headTilt: (Math.random() - 0.5) * 0.55,
      sway: 0.6 + Math.random() * 0.8,
      phase: Math.random() * TAU,
      size: 0.92 + Math.random() * 0.16
    };
    if (v.crawl) {
      torso.rotation.x = 0.7;
      neck.rotation.x = 0.6;
    }
    return root;
  }
  Z3.ZOMBIE_VARIANTS = VARIANTS;
  Z3.zombieMaterials = zombieMaterials;
})(window.Z3);","path":"C:\kamlesh\test\games\zombie3\js\zombie.js"}}

