{"toolCallId":"call_5cf0fd201aaf471eaf1ab9c2","toolName":"editor","input":{"new_text":"  Z3.zombieMaterials = zombieMaterials;

  /* ======================================================= the zombie == */
  function Zombie(world, type, x, z, opts) {
    opts = opts || {};
    this.world = world;
    this.game = opts.game || null;
    this.type = VARIANTS[type] ? type : 'walker';
    this.def = VARIANTS[this.type];
    this.mats = zombieMaterials(opts.matIndex || 0);
    this.pos = new THREE.Vector3(x, world.groundY(x, z), z);
    this.vel = new THREE.Vector3();
    this.yaw = Math.random() * TAU;
    this.hp = this.def.hp * (opts.hpScale || 1);
    this.maxHp = this.hp;
    this.dmgScale = opts.dmgScale || 1;
    this.speedMul = opts.speedScale || 1;
    this.state = 'idle';
    this.stateT = Z3.rand(0.2, 2.5);
    this.gait = Math.random() * TAU;
    this.moveSpeed = 0;
    this.alert = 0;
    this.target = null;
    this.percT = Math.random() * 0.4;
    this.growlT = Z3.rand(3, 12);
    this.stagger = 0;
    this.limbHp = { arm0: 34, arm1: 34, leg0: 46, leg1: 46 };
    this.dead = false;
    this.deadT = 0;
    this.fallAxis = new THREE.Vector3(Math.random() - 0.5, 0, Math.random() - 0.5).normalize();
    this.fallDir = Math.random() < 0.5 ? 1 : -1;
    this.bob = 0;
    this.bloodPooled = false;
    this.sep = new THREE.Vector3();
    this.hurtFlash = 0;
    this.struck = false;
    this.distToPlayer = 999;
    this.radius = 0.4 * this.def.scale;
    this.height = 1.85 * this.def.scale;
    buildBody(this);
    this.root.position.copy(this.pos);
    this.root.rotation.y = this.yaw;
    const scale = this.quirk.size * (opts.scaleMul || 1);
    this.root.scale.setScalar(scale);
    this.height = 1.85 * scale;
    (world.zombieGroup || world.cityGroup).add(this.root);
  }

  /* ------------------------------------------------------ animation ----- */
  Zombie.prototype.animate = function (dt) {
    const v = this.def;
    const a = this.arms, l = this.legs;
    if (this.dead) {
      // ragdoll-lite: topple over, limbs go limp
      this.deadT += dt;
      const t = Math.min(1, this.deadT / 1.1);
      const ease = 1 - Math.pow(1 - t, 3);
      this.root.rotation.z = this.fallAxis.z * ease * 1.5 * this.fallDir;
