  /* ==================================================== damage + death == */
  Zombie.ZONE_MUL = { head: 3.6, torso: 1.0, limb: 0.72, leg: 0.62 };

  /** Which limb index / kind a mesh belongs to (-1 when not a limb). */
  Zombie.prototype.partIndex = function (mesh) {
    for (let i = 0; i < 2; i++) {
      const a = this.arms[i];
      if (mesh === a.upperMesh || mesh === a.foreMesh || mesh === a.hand) return { arm: true, i: i };
      const l = this.legs[i];
      if (mesh === l.upper || mesh === l.lower) return { arm: false, i: i };
    }
    return null;
  };

  /**
   * Apply damage from a bullet / melee hit.
   * zone: 'head' | 'torso' | 'limb' | 'leg', dir = shot direction (normalised)
   */
  Zombie.prototype.hit = function (zone, dmg, dirX, dirZ, point, mesh) {
    if (this.dead) return 0;
    const mul = Zombie.ZONE_MUL[zone] || 1;
    const applied = dmg * mul;
    this.hp -= applied;
    this.alert = 1;
    this.hurtFlash = 0.18;
    this.stagger = Math.min(1, this.stagger + applied / 55);
    const g = this.game;
    const dist = clamp(this.distToPlayer / 40, 0, 0.9);
    if (g && g.fx && point) {
      g.fx.blood(point, { x: dirX, y: 0.45, z: dirZ }, zone === 'head' ? 20 : 9, zone === 'head' ? 1.4 : 1);
      if (zone === 'head') g.fx.mist(point, { x: dirX, y: 0.2, z: dirZ }, 6);
    }
    if (Z3Audio) {
      Z3Audio.play(zone === 'head' ? 'headshot' : 'impactFlesh', { volume: 0.5, distance: dist });
      Z3Audio.play('zombieHurt', { volume: 0.28, rate: 0.9 + Math.random() * 0.3, distance: dist });
    }
    if ((zone === 'limb' || zone === 'leg') && mesh) {
      const info = this.partIndex(mesh);
      if (info) {
        const key = (info.arm ? 'arm' : 'leg') + info.i;
        this.limbHp[key] -= applied;
        if (this.limbHp[key] <= 0) this.dismember(info, dirX, dirZ, point);
      }
    }
    if (this.hp <= 0) this.die(dirX, dirZ, zone === 'head');
    else if (this.state === 'idle' || this.state === 'wander') {
      this.setState('chase');
      this.target = null;
    }
    return applied;
  };

  Zombie.prototype.setState = function (s) {
    if (this.state === s) return;
    this.state = s;
    this.stateT = 0;
    this.struck = false;
  };

  Zombie.prototype.dismember = function (info, dirX, dirZ, point) {
    const g = this.game;
    if (info.arm) {
      const a = this.arms[info.i];
      a.upperMesh.visible = false;
      a.foreMesh.visible = false;
      a.hand.visible = false;
      a.missing = true;
      this.removeParts([a.upperMesh, a.foreMesh, a.hand]);
    } else {
      const l = this.legs[info.i];
      l.upper.visible = false;
      l.lower.visible = false;
      l.foot.visible = false;
      l.missing = true;
      this.removeParts([l.upper, l.lower]);
    }
    this.stagger = 1;
    if (g && g.fx) {
      g.fx.blood(point || this.pos, { x: dirX, y: 0.4, z: dirZ }, 26, 1.5);
      g.fx.blood({ x: this.pos.x, y: this.pos.y + 0.9, z: this.pos.z }, { x: dirX, y: 0.3, z: dirZ }, 16, 1.2);
      if (g.decals && g.tex) g.decals.pool(g.tex.pool, { x: this.pos.x, z: this.pos.z }, 1.1 + Math.random());
    }
    if (Z3Audio) Z3Audio.play('impactFlesh', { volume: 0.6, distance: clamp(this.distToPlayer / 40, 0, 0.9) });
    this.hp -= 18;
    if (this.hp <= 0) this.die(dirX, dirZ, false);
