  /* ======================================================== horde AI ==== */
  /** Per-frame perception, state machine and movement. */
  Zombie.prototype.update = function (dt, player) {
    this.stateT += dt;
    if (this.dead) {
      this.root.position.copy(this.pos);
      this.animate(dt);
      return;
    }
    const dx = player.position.x - this.pos.x;
    const dz = player.position.z - this.pos.z;
    this.distToPlayer = Math.hypot(dx, dz);
    this.alert = Math.max(0, this.alert - dt * 0.05);
    this.stagger = Math.max(0, this.stagger - dt * 1.8);

    // staggered perception so the horde never raycasts in a single frame
    this.percT -= dt;
    let sees;
    if (this.percT <= 0) {
      this.percT = 0.24 + Math.random() * 0.25;
      sees = this.canSee(player);
      this.seesPlayer = sees;
      if (sees) {
        if (this.alert < 0.6 && this.type === 'runner' && Z3Audio) {
          Z3Audio.play('zombieScream', {
            volume: 0.5 * clamp(1 - this.distToPlayer / 45, 0, 1),
            distance: clamp(this.distToPlayer / 45, 0, 0.9)
          });
        }
        this.alert = 1;
        this.target = null;
      }
    } else {
      sees = !!this.seesPlayer && this.distToPlayer < this.def.sight * 1.2;
    }

    // ambient growls, panned to the zombie's side of the player's view
    this.growlT -= dt;
    if (this.growlT <= 0) {
      this.growlT = Z3.rand(3, 11);
      if (this.distToPlayer < 34 && Z3Audio) {
        const rx = dx * Math.cos(-player.yaw) - dz * Math.sin(-player.yaw);
        Z3Audio.play('zombieGrowl', {
          volume: 0.34 * clamp(1 - this.distToPlayer / 34, 0, 1),
          distance: clamp(this.distToPlayer / 42, 0, 0.9),
          pan: clamp(rx / 14, -1, 1)
        });
      }
    }

    if (sees) {
      this.setState(this.distToPlayer < 2.3 ? 'attack' : 'chase');
    } else if (this.alert > 0.4 && this.state !== 'attack') {
      this.setState(this.target ? 'investigate' : 'chase');
    } else if ((this.state === 'chase' || this.state === 'investigate') && this.stateT > 7) {
      this.setState('wander');
      this.target = null;
    }

    let dirX = 0, dirZ = 0, speed = 0;
    switch (this.state) {
      case 'idle':
        if (this.stateT > Z3.rand(1.5, 4.5)) this.setState('wander');
        break;
      case 'wander':
        if (!this.target || this.stateT > 6 || Z3.dist2D(this.pos.x, this.pos.z, this.target.x, this.target.z) < 1.4) {
          this.target = this.world.randomPointNear(this.pos.x, this.pos.z, 9) || { x: this.pos.x, z: this.pos.z };
          this.stateT = 0;
        }
        dirX = this.target.x - this.pos.x;
        dirZ = this.target.z - this.pos.z;
        speed = this.def.speed * 0.6;
        break;
      case 'investigate':
        if (this.target) {
          dirX = this.target.x - this.pos.x;
          dirZ = this.target.z - this.pos.z;
          speed = this.def.speed * 1.3;
          if (Math.hypot(dirX, dirZ) < 1.6) { this.target = null; this.setState('wander'); }
        } else {
          this.setState('chase');
        }
        break;
      case 'chase':
        dirX = dx; dirZ = dz;
        speed = this.def.chaseSpeed * (this.alert > 0.7 ? 1 : 0.85);
        if (!sees && this.distToPlayer > 26 && this.stateT > 3) {
          this.target = { x: player.position.x, z: player.position.z };
          this.setState('investigate');
        }
        break;
      case 'attack':
        dirX = dx; dirZ = dz; speed = 0;
        if (this.stateT > 0.42 && !this.struck) {
          this.struck = true;
          if (this.distToPlayer < 2.2 + this.def.scale * 0.35 + 0.5) {
            player.damage(this.def.dmg * this.dmgScale, this.pos, this.type);
            if (Z3Audio) Z3Audio.play('zombieAttack', { volume: 0.5, distance: clamp(this.distToPlayer / 40, 0, 0.9) });
          }
        }
        if (this.stateT > 1.3) this.setState(sees ? (this.distToPlayer < 2.3 ? 'attack' : 'chase') : 'chase');
        break;
    }

    if (speed > 0) {
      const len = Math.hypot(dirX, dirZ) || 1;
      const moved = this.steer(dt, dirX / len + this.sep.x * 1.1, dirZ / len + this.sep.z * 1.1, speed);
      this.moveSpeed = moved ? speed : speed * 0.25;
    } else {
      this.moveSpeed = 0;
      const len = Math.hypot(dx, dz) || 1;
      this.yaw = Z3.dampAngle(this.yaw, Math.atan2(dx / len, dz / len), 6, dt);
    }
    this.pos.y = this.world.groundY(this.pos.x, this.pos.z);
    this.root.position.copy(this.pos);
    this.root.rotation.y = this.yaw;
    this.animate(dt);
  };

  Zombie.prototype.steer = function (dt, dirX, dirZ, speed) {
    const world = this.world;
    const r = this.radius + 0.05;
    const baseA = Math.atan2(dirZ, dirX);
    const offsets = [0, 0.45, -0.45, 0.95, -0.95, 1.55, -1.55, 2.2, -2.2];
    for (let i = 0; i < offsets.length; i++) {
      const a = baseA + offsets[i];
      const nx = Math.cos(a), nz = Math.sin(a);
      if (world.isFree(this.pos.x + nx * (r + 0.6), this.pos.z + nz * (r + 0.6), r, this.pos.y + 0.9)) {
        const step = speed * dt;
        this.pos.x += nx * step;
        this.pos.z += nz * step;
        this.yaw = Z3.dampAngle(this.yaw, Math.atan2(nx, nz), 5.5, dt);
        const b = world.bounds;
        this.pos.x = clamp(this.pos.x, b.min, b.max);
        this.pos.z = clamp(this.pos.z, b.min, b.max);
        return true;
      }
    }
    return false;
  };
