  /* -------------------------------------------------------- perception - */
  /** Line of sight + range check (flashlight/sprint make you easier to spot). */
  Zombie.prototype.canSee = function (player) {
    const p = player.position || player.pos;
    const def = this.def;
    const dx = p.x - this.pos.x, dz = p.z - this.pos.z;
    const d = Math.hypot(dx, dz);
    let range = def.sight;
    if (player.flashlightOn) range *= 1.4;
    if (player.crouching) range *= 0.8;
    if (player.sprinting) range *= 1.15;
    if (d > range || d > 45) return false;
    const eyeY = this.pos.y + this.height * 0.75;
    if (this.world.grid.lineBlocked(this.pos.x, this.pos.z, p.x, p.z, Math.max(1.5, eyeY))) return false;
    const facing = Math.cos(Z3.angleDelta(this.yaw, Math.atan2(dx, dz)));
    if (d < 6) return true;
    return facing > 0.1;
  };

  /* ====================================================== the manager === */
  /** Owns the horde: spawning, neighbour separation, updates, clean-up. */
  function ZombieManager(world, game) {
    this.world = world;
    this.game = game;
    this.list = [];
    this.targets = [];
    this.matIndex = 0;
    this.grid = new Z3.Grid(4);
    this._bs = [];
    this.count = 0;
  }
  ZombieManager.prototype.spawn = function (type, x, z, opts) {
    opts = opts || {};
    if (!opts.matIndex) opts.matIndex = this.matIndex++;
    opts.game = this.game;
    const zed = new Zombie(this.world, type, x, z, opts);
    zed.manager = this;
    if (!zed.sep) zed.sep = new THREE.Vector3();
    this.list.push(zed);
    return zed;
  };
  ZombieManager.prototype.alive = function () {
    let n = 0;
    for (let i = 0; i < this.list.length; i++) if (!this.list[i].dead) n++;
    return n;
  };
  ZombieManager.prototype.clear = function () {
    for (let i = 0; i < this.list.length; i++) {
      const z = this.list[i];
      if (z.root && z.root.parent) z.root.parent.remove(z.root);
    }
    this.list.length = 0;
    this.targets.length = 0;
    this.count = 0;
  };
  /** Gunshots, screams and explosions wake everything within earshot. */
  ZombieManager.prototype.alertNoise = function (x, z, radius, strength) {
    const s = strength === undefined ? 1 : strength;
    let woke = 0;
    for (let i = 0; i < this.list.length; i++) {
      const zed = this.list[i];
      if (zed.dead) continue;
      const d = Z3.dist2D(x, z, zed.pos.x, zed.pos.z);
      const hear = radius * zed.def.hear;
      if (d > hear) continue;
      zed.alert = Math.max(zed.alert, s * clamp(1 - d / hear, 0.3, 1));
      zed.target = { x: x, z: z };
      if (zed.state === 'idle' || zed.state === 'wander') zed.setState('investigate');
      woke++;
    }
