  /* --------------------------------------------------- the controller -- */
  const flashMat = new THREE.MeshBasicMaterial({ color: 0xffd08a, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false });

  function WeaponController(game, camera) {
    this.game = game;
    this.camera = camera;
    this.holder = new THREE.Group();
    camera.add(this.holder);
    this.models = {};
    this.slots = ORDER.slice();
    this.states = {};
    for (let i = 0; i < ORDER.length; i++) {
      const name = ORDER[i];
      const w = WEAPONS[name];
      this.states[name] = { mag: w.mag, reserve: w.reserve };
      const model = buildModel(name);
      model.group.visible = false;
      const flash = new THREE.Mesh(Z3.GEO.cyl, flashMat.clone());
      flash.scale.set(0.07, 0.14, 0.07);
      flash.rotation.x = Math.PI / 2;
      flash.position.copy(model.muzzle.position);
      flash.visible = false;
      model.group.add(flash);
      model.flash = flash;
      this.holder.add(model.group);
      this.models[name] = model;
    }
    this.slot = 1;
    this.current = null;
    this.cool = 0;
    this.reloading = false;
    this.reloadT = 0;
    this.reloadTotal = 0;
    this.adsWanted = false;
    this.adsAmount = 0;
    this.bob = 0;
    this.swayX = 0;
    this.swayY = 0;
    this.recoil = 0;
    this.recoilVel = 0;
    this.kick = 0;
    this.kickVel = 0;
    this.pumpT = 0;
    this.muzzleT = 0;
    this.meleeT = 0;
    this.trigger = false;
    this.raycaster = new THREE.Raycaster();
    this.flashLight = new THREE.PointLight(0xffcf9a, 0, 13, 2);
    this.flashLight.position.set(0.08, -0.06, -0.45);
    camera.add(this.flashLight);
    this.equip(ORDER[this.slot]);
  }

  WeaponController.prototype.def = function () { return WEAPONS[this.current]; };
  WeaponController.prototype.state = function () { return this.states[this.current]; };

  WeaponController.prototype.equip = function (name) {
    if (!WEAPONS[name] || this.current === name) return;
    for (const k in this.models) this.models[k].group.visible = false;
    this.current = name;
    this.slot = this.slots.indexOf(name);
    this.models[name].group.visible = true;
    this.reloading = false;
    this.reloadT = 0;
    this.cool = Math.max(this.cool, 0.3);
    if (Z3Audio) Z3Audio.play('safetyClick', { volume: 0.4 });
    if (this.game) this.game.hudDirty = true;
  };
  WeaponController.prototype.equipSlot = function (i) {
    if (i >= 0 && i < this.slots.length) this.equip(this.slots[i]);
  };
  WeaponController.prototype.cycle = function (dir) {
    const n = this.slots.length;
    const i = (this.slots.indexOf(this.current) + (dir > 0 ? 1 : -1) + n) % n;
    this.equip(this.slots[i]);
  };

  /** Effective spread (radians) from stance, movement and fatigue. */
  WeaponController.prototype.spread = function () {
    const w = this.def();
    if (w.melee) return 0;
    const base = this.adsAmount > 0.5 ? w.spread.ads : w.spread.hip;
    const p = this.game.player;
    const move = Math.hypot(p.velocity.x, p.velocity.z);
    let mul = 1 + move * 0.15;
    if (p.crouching) mul *= 0.62;
    if (p.sprinting) mul *= 1.8;
    if (p.stamina < 25) mul *= 1.35;
    return base * mul;
  };

  WeaponController.prototype.startReload = function () {
    const w = this.def(), st = this.state();
    if (w.melee || this.reloading || st.reserve <= 0 || st.mag >= w.mag) return false;
    this.reloading = true;
    this.reloadT = 0;
    this.reloadTotal = w.reload;
