  /** One trigger pull / melee swing. */
  WeaponController.prototype.fireOnce = function () {
    const w = this.def(), st = this.state();
    if (this.cool > 0 || this.reloading) return false;
    if (w.melee) {
      this.cool = w.rate;
      this.meleeT = 0.34;
