      const origin = this.camera.getWorldPosition(new THREE.Vector3());
      const dir = this.camera.getWorldDirection(new THREE.Vector3());
      this.raycaster.set(origin, dir);
      this.raycaster.far = w.reach;
      const hz = this.raycaster.intersectObjects(this.game.zombies.targets, false);
      if (hz.length) this.applyHit(hz[0], w.dmg, dir, true);
      return true;
    }
    if (st.mag <= 0) {
      if (Z3Audio) Z3Audio.play('dryFire', { volume: 0.55 });
      this.cool = 0.28;
      this.startReload();
      return false;
    }
    st.mag--;
    this.cool = w.rate;
    this.game.hudDirty = true;
    const p = this.game.player;
    const spread = this.spread();
    const origin = this.camera.getWorldPosition(new THREE.Vector3());
    const dir = this.camera.getWorldDirection(new THREE.Vector3());
    const right = new THREE.Vector3().crossVectors(dir, new THREE.Vector3(0, 1, 0)).normalize();
    const up = new THREE.Vector3().crossVectors(right, dir).normalize();
    const pellets = w.pellets || 1;
    for (let i = 0; i < pellets; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = Math.sqrt(Math.random()) * spread;
      const d = dir.clone()
        .addScaledVector(right, Math.cos(a) * r)
        .addScaledVector(up, Math.sin(a) * r)
        .normalize();
      this.raycaster.set(origin, d);
      this.raycaster.far = 150;
      const hz = this.raycaster.intersectObjects(this.game.zombies.targets, false);
      const hw = this.game.worldMeshes.length
        ? this.raycaster.intersectObjects(this.game.worldMeshes, false) : [];
      const zd = hz.length ? hz[0].distance : Infinity;
      const wd = hw.length ? hw[0].distance : Infinity;
      if (zd <= wd && hz.length) this.applyHit(hz[0], w.dmg, d, false);
      else if (hw.length) this.impact(hw[0], d);
    }
    // muzzle flash + light + recoil + noise
    const model = this.models[this.current];
    model.flash.visible = true;
    model.flash.rotation.z = Math.random() * 6.28;
    this.muzzleT = 0.045;
    this.flashLight.intensity = 3.4;
    this.recoilVel += w.recoil * 22;
    this.kickVel -= w.kick * 26;
    p.kickCamera(w.recoil * 0.55, w.kick * 0.35);
    this.game.shake.add(w.recoil * 2.2);
