    if (name.indexOf('metal') >= 0 || name.indexOf('windowGrid') >= 0 || name.indexOf('carPaint') >= 0) kind = 'Metal';
    else if (name.indexOf('wood') >= 0 || name.indexOf('crate') >= 0 || name.indexOf('bark') >= 0) kind = 'Wood';
    else if (name.indexOf('dirt') >= 0 || name.indexOf('grassDry') >= 0) kind = 'Dirt';
    const n = hit.face
      ? hit.face.normal.clone().transformDirection(hit.object.matrixWorld)
      : new THREE.Vector3(0, 1, 0);
    const p = { x: hit.point.x, y: hit.point.y, z: hit.point.z };
    const col = kind === 'Metal' ? [0.72, 0.72, 0.74] : (kind === 'Wood' ? [0.46, 0.34, 0.2] : [0.5, 0.48, 0.44]);
    g.fx.sparks(p, { x: n.x, y: n.y, z: n.z }, kind === 'Metal' ? 7 : 2);
    g.fx.dust(p, 4, col);
    if (g.decals && g.tex) g.decals.bulletHole(g.tex.hole, p, { x: n.x, y: n.y, z: n.z }, 0.12 + Math.random() * 0.07);
