  };

  /** Per-frame viewmodel animation, recoil springs, reload and autofire. */
  WeaponController.prototype.update = function (dt, input) {
    const w = this.def(), st = this.state();
    const p = this.game.player;
    this.cool = Math.max(0, this.cool - dt);
    this.muzzleT = Math.max(0, this.muzzleT - dt);
    this.meleeT = Math.max(0, this.meleeT - dt);
    this.flashLight.intensity *= Math.pow(0.002, dt);
    const model = this.models[this.current];
    model.flash.visible = this.muzzleT > 0;

    // recoil springs (muzzle rise + shoulder kick)
    this.recoilVel -= this.recoil * 260 * dt;
    this.recoilVel *= Math.pow(0.003, dt);
    this.recoil += this.recoilVel * dt;
    this.kickVel -= this.kick * 240 * dt;
    this.kickVel *= Math.pow(0.003, dt);
    this.kick += this.kickVel * dt;

    // ADS blend (blocked while sprinting or reloading)
    const wantAds = this.adsWanted && !this.reloading && !p.sprinting;
    this.adsAmount = Z3.damp(this.adsAmount, wantAds ? 1 : 0, 12, dt);

    if (this.reloading) {
      this.reloadT += dt;
      if (this.reloadT > this.reloadTotal * 0.6 && !this._magIn) {
        this._magIn = true;
        if (Z3Audio) Z3Audio.play('boltRack', { volume: 0.55 });
      }
      if (this.reloadT >= this.reloadTotal) {
        const need = w.mag - st.mag;
        const take = Math.min(need, st.reserve);
        st.mag += take;
        st.reserve -= take;
        this.reloading = false;
        this._magIn = false;
        this.game.hudDirty = true;
        if (Z3Audio) Z3Audio.play('magIn', { volume: 0.6 });
      }
    }

    // auto fire while the trigger is held; semi-auto needs a fresh press
    if (input.fireDown && (w.auto || !this.trigger) && this.cool <= 0 && !this.reloading) {
      this.fireOnce();
      this.trigger = true;
    }
    if (!input.fireDown) this.trigger = false;

    // pump shotgun cycling
    if (w.pump) {
      this.pumpT = (st.mag > 0 && !this.reloading && this.cool > 0)
        ? 1 - Math.min(1, this.cool / w.rate) : 0;
    }
