    onKill: function (zb, headshot) {
      this.kills++;
      if (headshot) this.headshots++;
      this.score += Math.round(zb.def.xp * (headshot ? 2.2 : 1) * (1 + this.wave * 0.06));
      this.hudDirty = true;
      this.hitMarker(headshot);
      this.killFeed(headshot ? 'HEADSHOT KILL' : zb.type.toUpperCase() + ' DOWN');
