    onZombieDeath: function () { /* the HUD refreshes via hudDirty */ },

    hitMarker: function (head) {
      const hm = document.getElementById('hitmarker');
      if (!hm) return;
      hm.classList.remove('show', 'head');
      void hm.offsetWidth;
      hm.classList.add('show');
      if (head) hm.classList.add('head');
