    showGameOver: function () {
      this.best.score = Math.max(this.best.score, this.score);
      this.best.wave = Math.max(this.best.wave, this.wave);
      this.best.kills = Math.max(this.best.kills, this.kills);
      try { localStorage.setItem(BEST_KEY, JSON.stringify(this.best)); } catch (e) { /* ignore */ }
      this.refreshBest();
      const set = function (id, v) {
        const el = document.getElementById(id);
        if (el) el.textContent = String(v);
      };
      set('finalScore', this.score);
      set('finalWave', this.wave);
      set('finalKills', this.kills);
      set('finalHead', this.headshots);
      document.getElementById('gameOver').classList.add('active');
      document.getElementById('hud').classList.add('hidden');
      if (Z3Audio) Z3Audio.setThreat(0);
    },

