    /* ------------------------------------------------- wave director -- */
    updateWaves: function (dt) {
      const p = this.player;
      if (this.waveState === 'intermission') {
        this.waveTimer -= dt;
        if (this.waveTimer <= 0) this.startWave(this.wave + 1);
        return;
      }
      // drip-feed spawns from the dark edges of the map
      if (this.toSpawn > 0) {
        this.spawnT -= dt;
        if (this.spawnT <= 0 && this.zombies.count() < 34) {
          this.spawnT = Math.max(0.5, 2.2 - this.wave * 0.12) * Z3.rand(0.7, 1.3);
          const group = 1 + (Math.random() < 0.35 ? 1 : 0) + (this.wave > 4 && Math.random() < 0.3 ? 1 : 0);
          for (let i = 0; i < group && this.toSpawn > 0; i++) {
            const pt = this.zombies.spawnPointFarFrom(p, 26);
            if (!pt) break;
            this.spawnZombie(pt.x + Z3.rand(-3, 3), pt.z + Z3.rand(-3, 3));
            this.toSpawn--;
          }
        }
      } else if (this.zombies.count() === 0) {
        this.waveState = 'intermission';
        this.waveTimer = 20;
        if (Z3Audio) Z3Audio.play('waveClear', { volume: 0.6 });
        this.banner('WAVE ' + this.wave + ' CLEARED', 'Resupply — next wave in 20s');
        this.dropSupplies(3);
        Z3Audio.setThreat(0.1);
      }
      Z3Audio.setThreat(clamp(this.zombies.count() / 16, 0, 1) * 0.85);
    },

    startWave: function (n) {
      this.wave = n;
      this.waveState = 'active';
      this.hpScale = 1 + (n - 1) * 0.13;
      this.speedScale = Math.min(1.5, 1 + (n - 1) * 0.045);
      this.toSpawn = Math.min(46, 5 + n * 3);
      this.spawnT = 1.2;
      this.hudDirty = true;
      this.banner('WAVE ' + n, this.toSpawn + ' hostiles inbound');
      if (Z3Audio) Z3Audio.play('waveStart', { volume: 0.55 });
      // unlock the arsenal as the nights get worse
      const st = this.weapons.states;
      const unlocks = [
        { wave: 2, name: 'smg', ammo: 90, msg: 'MP5 SMG ACQUIRED' },
        { wave: 3, name: 'shotgun', ammo: 24, msg: '12G PUMP ACQUIRED' },
        { wave: 4, name: 'rifle', ammo: 90, msg: 'AK-74 ACQUIRED' }
      ];
      for (let i = 0; i < unlocks.length; i++) {
        const u = unlocks[i];
        if (n >= u.wave && st[u.name].reserve === 0) {
          st[u.name].reserve = u.ammo;
          st[u.name].mag = Z3.WEAPONS[u.name].mag;
          this.killFeed(u.msg);
        }
      }
      this.dropSupplies(2);
    },

    spawnZombie: function (x, z) {
      const w = this.wave;
      let type = 'walker';
      const r = Math.random();
      if (w >= 3 && r < 0.22) type = 'runner';
      else if (w >= 5 && r < 0.30) type = 'brute';
      else if (w >= 2 && r < 0.42) type = 'crawler';
      this.zombies.spawn(type, x, z, {
        hpScale: this.hpScale,
        speedScale: this.speedScale * Z3.rand(0.92, 1.08),
        dmgScale: 1 + (w - 1) * 0.05,
        scaleMul: Z3.rand(0.95, 1.06)
      });
    },

    dropSupplies: function (n) {
      const spots = this.world.lootSpots;
      for (let i = 0; i < n; i++) {
        let x, z;
        if (spots.length && Math.random() < 0.6) {
          const s = spots[(Math.random() * spots.length) | 0];
          x = s.x; z = s.z;
        } else {
          const a = Math.random() * 6.283;
          const r = Z3.rand(8, 45);
          x = Math.cos(a) * r; z = Math.sin(a) * r;
        }
        this.spawnPickup(i === 0 && this.player.health < 70 ? 'health' : 'ammo', x, z);
      }
    },

    updatePickups: function (dt) {
      const p = this.player;
      for (let i = this.pickups.length - 1; i >= 0; i--) {
        const pk = this.pickups[i];
        pk.t += dt;
        pk.ring.rotation.z += dt * 1.6;
        pk.group.position.y = this.world.groundY(pk.group.position.x, pk.group.position.z) +
          Math.sin(pk.t * 2.2) * 0.05;
        const dx = pk.group.position.x - p.position.x;
        const dz = pk.group.position.z - p.position.z;
        if (!p.dead && dx * dx + dz * dz < 1.35) {
          if (pk.kind === 'ammo') {
            const st = this.weapons.states;
            const cur = this.weapons.current;
            if (cur !== 'knife') {
              st[cur].reserve += Math.ceil(Z3.WEAPONS[cur].mag * 2.2);
            } else {
              st.pistol.reserve += 24;
            }
            if (Z3Audio) Z3Audio.play('pickupAmmo', { volume: 0.7 });
            this.killFeed('AMMO SCROUNGED');
          } else {
            p.heal(38);
            if (Z3Audio) Z3Audio.play('pickupHealth', { volume: 0.7 });
            this.killFeed('BANDAGE USED');
          }
          this.scene.remove(pk.group);
          this.pickups.splice(i, 1);
          this.hudDirty = true;
        }
      }
    }
  };
