    /* ---------------------------------------------------- main loop --- */
    loop: function () {
      requestAnimationFrame(this._loop);
      const dt = Math.min(0.05, this.clock.getDelta());
      this.fpsAcc += dt;
      this.fpsFrames++;
      if (this.fpsAcc > 0.5) {
        this.fps = this.fpsFrames / this.fpsAcc;
        this.fpsAcc = 0;
        this.fpsFrames = 0;
      }
      if (this.running && !this.paused) {
        this.readKeys();
        this.player.update(dt, this.input);
        this.player.applyCamera(dt);
        this.weapons.update(dt, this.input);
        this.weapons.pose(dt);
        this.zombies.update(dt, this.player);
        this.updateWaves(dt);
        this.updatePickups(dt);
        this.updateFire(dt);
        this.fx.update(dt);
        this.decals.update(dt);
        this.shake.update(dt);
        this.world.update(dt, this.camera.position);
        // lightning on the horizon brightens the whole street for a beat
        this.hemi.intensity = 0.44 + this.world.lightning * 1.2;
        this.moon.intensity = 0.5 + this.world.lightning * 0.9;
        this.updateHud();
        this._mmT = (this._mmT || 0) + dt;
        if (this._mmT > 0.12) { this._mmT = 0; this.drawMinimap(); }
        if (this.selftest) this.selftestTick(dt);
      }
      this.renderer.render(this.scene, this.camera);
      this.input.lookDX = 0;
      this.input.lookDY = 0;
    },

    /** Burning barrels emit fire + smoke. */
    updateFire: function (dt) {
      for (let i = 0; i < this.world.firePoints.length; i++) {
        const f = this.world.firePoints[i];
        f.t = (f.t || 0) - dt;
        if (f.t > 0) continue;
        f.t = 0.05 + Math.random() * 0.07;
        const jx = Z3.rand(-0.12, 0.12), jz = Z3.rand(-0.12, 0.12);
        this.fx.emit({
          count: 1, x: f.x + jx, y: f.y, z: f.z + jz, spread: 0.05,
          dx: 0, dy: 1, dz: 0, up: 0.9, speed: 0.4, speedVar: 1,
          color: [1, 0.48, 0.1], colorVar: 0.35,
          size: 0.14, sizeVar: 0.7, life: 0.45, lifeVar: 0.6,
          gravity: -1.6, drag: 0.8, grow: 0.12, alpha: 0.85
        });
        if (Math.random() < 0.25) {
          this.fx.smoke({ x: f.x, y: f.y + 0.4, z: f.z }, 1, 0.34, [0.16, 0.16, 0.17]);
        }
      }
    },

    /* ------------------------------------------------------ selftest -- */
    selftestTick: function (dt) {
      this.stTime = (this.stTime || 0) + dt;
      this.stFrames = (this.stFrames || 0) + 1;
