   DEAD ZONE 3D  —  style.css
   HUD + menus. Palette matches the 2D DEAD ZONE build (--blood / --bone).
   ===================================================================== */
* { margin: 0; padding: 0; box-sizing: border-box; user-select: none; }

:root {
  --blood: #b3121c;
  --blood-dim: #6e0c13;
  --rust: #c63e1f;
  --bone: #e8d9b8;
  --steel: #2a2d31;
  --dark: #0d0e10;
  --warn: #ffb000;
}

html, body {
  width: 100%; height: 100%;
  overflow: hidden;
  background: #000;
  font-family: 'Segoe UI', 'Oswald', Impact, sans-serif;
  color: var(--bone);
}

#gameContainer { position: relative; width: 100vw; height: 100vh; background: #000; }
#gameCanvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

/* ------------------------------------------------------- overlays --- */
.overlay {
  position: absolute; inset: 0;
  display: none;
  align-items: center; justify-content: center;
  z-index: 100;
  background: radial-gradient(ellipse at center, rgba(18,6,6,0.78) 0%, rgba(0,0,0,0.95) 100%);
  backdrop-filter: blur(3px);
}
.overlay.active { display: flex; animation: fadeIn 0.35s ease; }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

.menu-content { text-align: center; padding: 34px; max-width: 620px; width: 92%; }

.title {
  font-size: clamp(46px, 9vw, 96px);
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--blood);
  text-transform: uppercase;
  text-shadow: 0 0 22px rgba(179,18,28,0.65), 0 0 55px rgba(179,18,28,0.35), 3px 3px 0 #1a0203;
  margin-bottom: 6px;
  animation: titlePulse 3.2s ease-in-out infinite;
}
.title.small { font-size: clamp(34px, 6vw, 60px); }
.title.dead { color: #8a8f94; text-shadow: 0 0 30px rgba(140,10,10,0.55), 3px 3px 0 #0a0505; }
@keyframes titlePulse {
  0%, 100% { text-shadow: 0 0 22px rgba(179,18,28,0.65), 0 0 55px rgba(179,18,28,0.35), 3px 3px 0 #1a0203; }
  50% { text-shadow: 0 0 34px rgba(179,18,28,0.95), 0 0 80px rgba(179,18,28,0.55), 3px 3px 0 #1a0203; }
}
.subtitle { letter-spacing: 0.32em; font-size: 13px; color: #9aa0a8; margin-bottom: 22px; }

.menu-stats { margin: 0 auto 20px; max-width: 300px; }
.stat-row {
  display: flex; justify-content: space-between;
  padding: 6px 10px; margin-bottom: 4px;
  background: rgba(255,255,255,0.04);
  border-left: 2px solid var(--blood-dim);
  font-size: 13px; letter-spacing: 0.18em;
}
.stat-row span:last-child { color: var(--bone); font-weight: 700; }

.btn {
  display: block; width: 100%; max-width: 320px; margin: 9px auto;
  padding: 13px 18px;
  font-size: 15px; font-weight: 700; letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--bone);
  background: linear-gradient(180deg, #23262b, #15171a);
  border: 1px solid #3a3e44;
  cursor: pointer;
  transition: all 0.15s ease;
}
.btn:hover { border-color: var(--blood); color: #fff; box-shadow: 0 0 18px rgba(179,18,28,0.35); transform: translateY(-1px); }
.btn-primary { background: linear-gradient(180deg, #7e1017, #4d090e); border-color: #a3161f; }
.btn-primary:hover { background: linear-gradient(180deg, #9c141d, #5d0b11); }
.btn-ghost { background: transparent; }

.howto { margin: 18px auto 6px; max-width: 460px; text-align: left; }
.howto.hidden { display: none; }
.key-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px 14px; margin-bottom: 12px; }
.key-grid div { display: flex; align-items: center; gap: 8px; font-size: 12px; color: #aab0b8; }
kbd {
  min-width: 52px; text-align: center;
  padding: 3px 6px; font-size: 11px; font-family: inherit;
  background: #1c1f23; border: 1px solid #3a3e44; border-bottom-width: 2px;
  color: var(--bone); letter-spacing: 0.08em;
}
.tip { font-size: 12px; line-height: 1.55; color: #8d939b; }

.settings { margin-top: 20px; display: grid; gap: 8px; }
.settings label {
  display: flex; align-items: center; gap: 12px;
  font-size: 11px; letter-spacing: 0.22em; color: #9aa0a8;
}
.settings input[type="range"] { flex: 1; accent-color: var(--blood); }
.settings span { min-width: 48px; text-align: right; color: var(--bone); }

/* --------------------------------------------------------- loader --- */
.loader { text-align: center; }
.loader p { margin-top: 14px; letter-spacing: 0.3em; font-size: 12px; color: #9aa0a8; }
.loader-bar { width: 260px; height: 4px; margin: 0 auto; background: #1a1d21; overflow: hidden; }
.loader-fill {
  width: 40%; height: 100%;
  background: var(--blood);
  animation: slide 1.1s ease-in-out infinite alternate;
}
@keyframes slide { from { transform: translateX(-60%); } to { transform: translateX(200%); } }
