.bar-fill { height: 100%; width: 100%; transition: width 0.18s ease; }
.bar-fill.health { background: linear-gradient(90deg, #6e0c13, var(--blood)); }
.bar-fill.health.low { animation: lowhp 0.8s ease-in-out infinite alternate; }
